local config = {
  ui_story_5087_50870100_1_dialog_content = "It's an ancient fable known to everyone in Northland.",
  ui_story_5087_50870100_2_dialog_content = "And the very first line is...",
  ui_story_5087_50870100_3_dialog_content = "\"Can you recall those beautiful white flowers?\"",
  ui_story_5087_50870100_4_dialog_content = "<color=#e8d9bb>After remembering the first sentence, the remaining memory fragments activate and rise one by one.</color>",
  ui_story_5087_50870100_5_dialog_content = "<color=#e8d9bb>A cheery fire burns in the fireplace, its warm light creating dancing shadows within the small cottage.</color>",
  ui_story_5087_50870100_6_dialog_content = "<color=#e8d9bb>In the fire's glow, four figures can be seen: a husband and wife, as well as their twin daughters who look like mirror images of one another.</color>",
  ui_story_5087_50870100_7_dialog_content = "\"Can you recall those beautiful white flowers? Two stems growing in harmony by the tranquil lake.\"",
  ui_story_5087_50870100_8_dialog_content = "\"One was a delicate narcissus, the other a pristine lily.\"",
  ui_story_5087_50870100_9_dialog_content = "\"Though distinct in form, their souls were one.\"",
  ui_story_5087_50870100_10_dialog_content = "\"One bore leaves, the other bloomed with flowers. They sipped the morning dew, their roots forever intertwined.\"",
  ui_story_5087_50870100_11_dialog_content = "Since they were so close, they must have lived together forever, right?",
  ui_story_5087_50870100_12_dialog_content = "Unfortunately, every story must have its twists.",
  ui_story_5087_50870100_13_dialog_content = "\"Under the falling gray snow, the pristine lily was soon buried.\"",
  ui_story_5087_50870100_14_dialog_content = "\"Left alone in the world, the white narcissus wept quietly.\"",
  ui_story_5087_50870100_15_dialog_content = "*sniffling* That poor lily... It must have been so cold under all of that snow.",
  ui_story_5087_50870100_16_dialog_content = "I feel more sorry for the narcissus. Wasn't there anyone who could help her?",
  ui_story_5087_50870100_17_dialog_content = "You're both such sweet little girls, just like the lily and the narcissus. Northland would ever leave you to cry all alone.",
  ui_story_5087_50870100_18_dialog_content = "Let's go back to the story—",
  ui_story_5087_50870100_19_dialog_content = "\"Lake Mirror noticed the cold roots and sad tears of the narcissus one day. Taking pity on her, the lake promised to bring back the lily's soul.\"",
  ui_story_5087_50870100_20_dialog_content = "What happened next? Did her soul come back?",
  ui_story_5087_50870100_21_dialog_content = "Did they get to live happily ever after again?",
  ui_story_5087_50870100_22_dialog_content = "Of course they did! How else could the story end?",
  ui_story_5087_50870100_23_dialog_content = "But it's well past your bedtime, girls. Let's just finish the story tomorrow, agreed?",
  ui_story_5087_50870100_24_dialog_content = "No way! I want to hear it now!",
  ui_story_5087_50870100_25_dialog_content = "You want to know if the narcissus still recognizes the lily's soul, don't you?",
  ui_story_5087_50870100_26_dialog_content = "Yeah! I also want to know if they get to be together again and live happily ever after!",
  ui_story_5087_50870100_27_dialog_content = "Of course they do. That's how every story goes, isn't it?",
  ui_story_5087_50870100_28_dialog_content = "No matter how many twists and turns the story takes...",
  ui_story_5087_50870100_29_dialog_content = "Everyone always gets to live happily ever after.",
  ui_story_5087_50870100_30_dialog_content = "That's right. Lola once said that every story has a happy ending.",
  ui_story_5087_50870100_31_dialog_content = "But after all these years, I can't even remember hearing this story, much less its ending.",
  ui_story_5087_50870100_32_dialog_content = "A sense of unease compelled me to seek answers, but all I could do was sift through the chaotic fragments of my memories in search of them.",
  ui_story_5087_50870100_33_dialog_content = "Then, as though my wish had been granted, I finally remembered something—",
  ui_story_5087_50870100_34_dialog_content = "A warm fireplace, a story told by a mother and father, and two playful little girls. It all felt so familiar, and yet so distant at the same time.",
  ui_story_5087_50870100_35_dialog_content = "Was it my past? I can hardly figure out who I am anymore, but the meaning behind that story's ending is clear and defined.",
  ui_story_5087_50870100_36_dialog_content = "I hoped and prayed with all my heart for that ending to come true, even if it meant... that I could never wake up again.",
  ui_story_5087_50870100_37_dialog_content = "<color=#e8d9bb>\"From that day on, a lily flower blossomed out of the narcissus, and they both lived happily ever after...\"</color>",
  ui_story_5087_50870100_38_dialog_content = "Happily... ever after...",
  ui_story_5087_50870100_39_dialog_content = "That's right, Nikinis. You and I will always be together, and live happily ever after.",
  ui_story_5087_50870100_40_dialog_content = "... Huh?",
  ui_story_5087_50870100_41_dialog_content = "<color=#e8d9bb>An intoxicating fragrance wafts across a field of flowers. The light scent of narcissuses and the rich scent of lilies intermingle in the air.</color>",
  ui_story_5087_50870100_42_dialog_content = "<color=#e8d9bb>In the fragrance of the flowers, someone holds hands with Nikinis.</color>",
  ui_story_5087_50870100_43_dialog_content = "<color=#e8d9bb>She is as pure and beautiful as a white lily. Though they differ in body and mind, their spirits are one.</color>",
  ui_story_5087_50870100_44_dialog_content = "N-Nepolis? Is it really you, sister?",
  ui_story_5087_50870100_45_dialog_content = "Why do you look so surprised, Nikinis? Don't tell me you got sick again and forgot what I look like.",
  ui_story_5087_50870100_46_dialog_content = "Of course not! But I thought you were trapped in...",
  ui_story_5087_50870100_47_dialog_content = "(... Trapped in what? Why can't I remember?)",
  ui_story_5087_50870100_48_dialog_content = "... Wait, Nepolis, don't go! Stay with me!",
  ui_story_5087_50870100_49_dialog_content = "Oh? Looks like I wasn't imagining things after all. Ever since we recovered from our illness, you've gotten a lot clingier.",
  ui_story_5087_50870100_50_dialog_content = "But don't worry, Nikinis. I'm really right here next to you.",
  ui_story_5087_50870100_51_dialog_content = "Not an illusion in a mirror, or a reflection in the water.",
  ui_story_5087_50870100_52_dialog_content = "Your face is so warm, Nepolis... Are you really back again?",
  ui_story_5087_50870100_53_dialog_content = "(... Why did I say \"back again\"?)",
  ui_story_5087_50870100_54_dialog_content = "Whenever we're together, it feels like I can't even hide my thoughts from you.",
  ui_story_5087_50870100_55_dialog_content = "I've always been able to tell what you're thinking, and the same goes for you and my thoughts. That's our gift and our way of showing that we'll always have each other.",
  ui_story_5087_50870100_56_dialog_content = "Now give me your hand and take a walk with me. You'll remember things soon enough.",
  ui_story_5087_50870100_57_dialog_content = "As twins, we share the same roots and stems. Born with very special Luminatics, our hearts and souls are connected.",
  ui_story_5087_50870100_58_dialog_content = "If I get thirsty...",
  ui_story_5087_50870100_59_dialog_content = "... Then I'll be thirsty too.",
  ui_story_5087_50870100_60_dialog_content = "If I decide to go outside...",
  ui_story_5087_50870100_61_dialog_content = "... I'll already have our coats and boots ready.",
  ui_story_5087_50870100_62_dialog_content = "That's right! Our looks, our hobbies, our talents... You and I are one and the same, Nikinis.",
  ui_story_5087_50870100_63_dialog_content = "We planted this field of flowers together, entered the Winter Palace together, and earned the honor of serving Queen Bethlehem together.",
  ui_story_5087_50870100_64_dialog_content = "You... really don't remember anything?",
  ui_story_5087_50870100_65_dialog_content = "No... I remember everything now. The more you tell me about our past, the more memories appear in my mind.",
  ui_story_5087_50870100_66_dialog_content = "Every time you smile with nostalgia, I feel the same happiness in my heart as well.",
  ui_story_5087_50870100_67_dialog_content = "Being with you makes me feel so... complete—or at least that's how I would describe it.",
  ui_story_5087_50870100_68_dialog_content = "I can't imagine living without you.",
  ui_story_5087_50870100_69_dialog_content = "You're talking about the time we both fell ill, right? That was such a scary time...",
  ui_story_5087_50870100_70_dialog_content = "I felt so weak and listless every single day. I couldn't even feel my own limbs, much less you.",
  ui_story_5087_50870100_71_dialog_content = "I think that was the first time we lost our connection to one another.",
  ui_story_5087_50870100_72_dialog_content = "That's right... I got sick too, which is why my memories and feelings have become so muddled.",
  ui_story_5087_50870100_73_dialog_content = "Hehe... Then we're still the same as when we were kids, sharing every moment of pain and sadness.",
  ui_story_5087_50870100_74_dialog_content = "To be honest, it's a little inconvenient. When one of us got sick, the other followed suit... Our parents must have been worried a lot!",
  ui_story_5087_50870100_75_dialog_content = "Our parents... That's right! Are they doing well? Can I go home and see them?",
  ui_story_5087_50870100_76_dialog_content = "Of course. But before we go home, we have to finish our mission.",
  ui_story_5087_50870100_77_dialog_content = "Our mission?",
  ui_story_5087_50870100_78_dialog_content = "What, did you forget all about Her Majesty's mission after one little nap?",
  ui_story_5087_50870100_79_dialog_content = "The queen ordered us to retrieve a lost artifact from the forest.",
  ui_story_5087_50870201_1_dialog_content = "We don't have much time, so let's do things the usual way. We'll clear out the snow as we move along!",
  ui_story_5087_50870201_2_dialog_content = "Okay!",
  ui_story_5087_50870201_3_dialog_content = "Our mission is to... retrieve a lost artifact for Queen Bethlehem?",
  ui_story_5087_50870201_4_dialog_content = "Yes. A relic was stolen from the treasure vault of the Winter Palace. It's a dangerous object that can disrupt a person's very spirit.",
  ui_story_5087_50870201_5_dialog_content = "The queen worries that it will cause untold suffering if it makes its way into people's hands, so she dispatched many of her loyal retainers to search for it.",
  ui_story_5087_50870201_6_dialog_content = "Stolen? What kind of thief would be foolish enough to do something like that?",
  ui_story_5087_50870201_7_dialog_content = "Heehee, I think a better question is what kind of queen would be this merciful about it?",
  ui_story_5087_50870201_8_dialog_content = "A priceless relic gets stolen from her palace, and her first concern is to retrieve it before it can threaten the safety of her people. For Her Majesty, apprehending the thief takes far less precedence.",
  ui_story_5087_50870201_9_dialog_content = "The queen has always been that way.",
  ui_story_5087_50870201_10_dialog_content = "I can't count the number of stories I've heard about Her Majesty resolving all kinds of problems for her people.",
  ui_story_5087_50870201_11_dialog_content = "Even if it was something as trivial as rescuing livestock from the forest or clearing snow from the mountain roads...",
  ui_story_5087_50870201_12_dialog_content = "At least we don't have to worry about snow, right? See how well we work together? Hey, this side's mine!",
  ui_story_5087_50870201_13_dialog_content = "The queen has taken care of us for as long as I can remember...",
  ui_story_5087_50870201_14_dialog_content = "She even cured my disease.",
  ui_story_5087_50870201_15_dialog_content = "That's why you chose to stay in the Winter Palace and serve her.",
  ui_story_5087_50870201_16_dialog_content = "I'm sure she cured your disease too.",
  ui_story_5087_50870201_17_dialog_content = "As long as you feel better, then so do I. There's no need to trouble the queen about it.",
  ui_story_5087_50870201_18_dialog_content = "One more! Phew, we finally made it.",
  ui_story_5087_50870201_19_dialog_content = "Someone reported seeing the stolen artifact somewhere near that cottage up ahead.",
  ui_story_5087_50870201_20_dialog_content = "Hello, is anybody home? We were sent by the Winter Palace.",
  ui_story_5087_50870201_21_dialog_content = "<color=#e8d9bb>The inside of the cottage is deathly silent.</color>",
  ui_story_5087_50870201_22_dialog_content = "(No response... Huh? I stepped on something shiny... a broken shard of some kind?)",
  ui_story_5087_50870201_23_dialog_content = "What is it, Nikinis?",
  ui_story_5087_50870201_24_dialog_content = "Be careful, Nepolis. I have...",
  ui_story_5087_50870201_25_dialog_content = "... A bad feeling about this.",
  ui_story_5087_50870201_26_dialog_content = "<color=#e8d9bb>The twin sisters each place a hand on the door. Standing on either side of it, they carefully push it open.</color>",
  ui_story_5087_50870201_27_dialog_content = "!",
  ui_story_5087_50870201_28_dialog_content = "Is that... a mirror?",
  ui_story_5087_50870201_29_dialog_content = "It's completely broken...",
  ui_story_5087_50870201_30_dialog_content = "(What's happening? For some reason, this mirror feels so familiar to me...)",
  ui_story_5087_50870201_31_dialog_content = "(Huh? Did I just see a person in the mirror?)",
  ui_story_5087_50870201_32_dialog_content = "Nikinis... Nikinis...",
  ui_story_5087_50870201_33_dialog_content = "Who are you? Why are you calling out to me? And... what are you doing in this mirror?",
  ui_story_5087_50870201_34_dialog_content = "Nikinis... No...",
  ui_story_5087_50870201_35_dialog_content = "I can't hear you.",
  ui_story_5087_50870201_36_dialog_content = "Stop! Don't take another step!",
  ui_story_5087_50870201_37_dialog_content = "!",
  ui_story_5087_50870201_38_dialog_content = "That's the stolen relic from the Winter Palace, Nikinis!",
  ui_story_5087_50870201_39_dialog_content = "It's called the Northland Mirror, and it's one of the most dangerous objects in the queen's collection!",
  ui_story_5087_50870201_40_dialog_content = "What?",
  ui_story_5087_50870201_41_dialog_content = "(Then why would someone inside this dangerous artifact call out to me?)",
  ui_story_5087_50870201_42_dialog_content = "Look out, Nikinis!",
  ui_story_5087_50870201_43_dialog_content = "<color=#e8d9bb>Startled, Nikinis only manages to see the scattered shards of the mirror begin to tremble.</color>",
  ui_story_5087_50870201_44_dialog_content = "<color=#e8d9bb>Suddenly, countless beams of darkness erupt from the shards and converge.</color>",
  ui_story_5087_50870201_45_dialog_content = "<color=#e8d9bb>An indistinct presence, not unlike a shadow.</color>",
  ui_story_5087_50870201_46_dialog_content = "Keep away from my sister!",
  ui_story_5087_50870202_1_dialog_content = "Nepolis! Are you hurt? I can feel your pain—",
  ui_story_5087_50870202_2_dialog_content = "This isn't the time to keep our connection, silly. If you share in my pain, both of our lives will be in danger in battles.",
  ui_story_5087_50870202_3_dialog_content = "I'm sorry... But you got hurt because of me...",
  ui_story_5087_50870202_4_dialog_content = "It couldn't be helped. After all, you would've done the same for me, right?",
  ui_story_5087_50870202_5_dialog_content = "What happened to you just now? It wasn't like you at all to approach that magic mirror so recklessly.",
  ui_story_5087_50870202_6_dialog_content = "I'm having a hard time understanding your emotions right now...",
  ui_story_5087_50870202_7_dialog_content = "It's just that... I saw someone moving in the mirror, so I wanted to take a closer look.",
  ui_story_5087_50870202_8_dialog_content = "You saw someone? Are you sure those weren't just our reflections?",
  ui_story_5087_50870202_9_dialog_content = "I... don't think so? Let me go take another look—",
  ui_story_5087_50870202_10_dialog_content = "I don't think that's a good idea. That mirror is way too dangerous, and there's no telling what might happen to us if we get near it.",
  ui_story_5087_50870202_11_dialog_content = "We'll use our Luminatics to bundle it up and transport it back to the Winter Palace.",
  ui_story_5087_50870202_12_dialog_content = "... You're right, Nepolis. Let's begin.",
  ui_story_5087_50870202_13_dialog_content = "<color=#e8d9bb>The two sisters activate their Luminatics simultaneously. Green branches grow out of the ground on either side of the mirror and bloom with white flowers.</color>",
  ui_story_5087_50870202_14_dialog_content = "<color=#e8d9bb>Soon, the entire cottage is filled with the smell of flowers. As the blooming branches climb up the walls of the cottage, the broken mirror is wrapped up tightly.</color>",
  ui_story_5087_50870202_15_dialog_content = "Urgh! There's something in the mirror... and it's trying to get out!",
  ui_story_5087_50870202_16_dialog_content = "Just hang on! I'm coming!",
  ui_story_5087_50870202_17_dialog_content = "Phew...",
  ui_story_5087_50870202_18_dialog_content = "Heheh, looks like we pulled it off, huh? I expected nothing less from us sisters!",
  ui_story_5087_50870202_19_dialog_content = "You deserve all the credit, Nepolis... It's been so long since my last fight that I forgot to take precautions.",
  ui_story_5087_50870202_20_dialog_content = "I don't think I could've handled this without you...",
  ui_story_5087_50870202_21_dialog_content = "Not at all! I can tell how powerful you are just from looking at these flowers.",
  ui_story_5087_50870202_22_dialog_content = "See? Just look at how well they're blooming!",
  ui_story_5087_50870202_23_dialog_content = "<color=#e8d9bb>By the power of their Luminatics, the cottage is buried under a sea of pure-white flowers.</color>",
  ui_story_5087_50870202_24_dialog_content = "<color=#e8d9bb>Delicate narcissuses and pristine lilies, born side by side.</color>",
  ui_story_5087_50870202_25_dialog_content = "Our flowers blooming together... For some reason, it feels like I haven't seen something like this for a long time...",
  ui_story_5087_50870202_26_dialog_content = "\"Can you recall those beautiful white flowers?\"",
  ui_story_5087_50870202_27_dialog_content = "Nepolis' flowers... Ah.",
  ui_story_5087_50870202_28_dialog_content = "I'm right here, remember? You don't have to keep staring at my flowers, you know.",
  ui_story_5087_50870202_29_dialog_content = "Once we return from the Winter Palace, we can go back to Lake Mirror and tend to our flower field!",
  ui_story_5087_50870300_1_dialog_content = "<color=#e8d9bb>The Winter Palace is the seat of royal authority in Northland and a place long considered sacred by Northlanders.</color>",
  ui_story_5087_50870300_2_dialog_content = "Amazing... You two actually managed to retrieve the Northland Mirror! I can hardly believe it!",
  ui_story_5087_50870300_3_dialog_content = "It was all thanks to my sister...",
  ui_story_5087_50870300_4_dialog_content = "Don't be so modest, Nikinis! Look, they even served us some of Her Majesty's most prized tea.",
  ui_story_5087_50870300_5_dialog_content = "This stuff isn't cheap, you know? The last time I wanted a cup, I begged them for three days straight, but they still turned me down.",
  ui_story_5087_50870300_6_dialog_content = "Hahaha, well... As you know, the theft of the Northland Mirror was quite a serious matter!",
  ui_story_5087_50870300_7_dialog_content = "They say this relic is even older than the Winter Palace and it commands a very unique place within the queen's collection.",
  ui_story_5087_50870300_8_dialog_content = "For it to go missing in the middle of the night without a trace... poor Master Novio has hardly slept since then!",
  ui_story_5087_50870300_9_dialog_content = "Now that it's back in our possession, the royal can spare themselves even more sleepless nights... at least for now! Hahaha!",
  ui_story_5087_50870300_10_dialog_content = "We're honored to help Master Novio with something so important. Unfortunately, we haven't found any clues regarding the thief...",
  ui_story_5087_50870300_11_dialog_content = "...",
  ui_story_5087_50870300_12_dialog_content = "Hmm? What's the matter, Nikinis? You look uneasy... Are you nervous about being in the great Winter Palace?",
  ui_story_5087_50870300_13_dialog_content = "Honestly, I wish you wouldn't tease me so much sometimes.",
  ui_story_5087_50870300_14_dialog_content = "It's just... The Winter Palace seems a little different today.",
  ui_story_5087_50870300_15_dialog_content = "What's different about it?",
  ui_story_5087_50870300_16_dialog_content = "(I'm not sure... Why is it so hard to remember what the Winter Palace looked like before?)",
  ui_story_5087_50870300_17_dialog_content = "I can't quite put my finger on it... Maybe it just looks especially clean today? It's so bright and clear that it feels like something's missing...",
  ui_story_5087_50870300_18_dialog_content = "And here I thought you were all about cleanliness.",
  ui_story_5087_50870300_19_dialog_content = "Your Majesty!",
  ui_story_5087_50870300_20_dialog_content = "Y-Your Majesty! Please forgive us if our bickering offended you...",
  ui_story_5087_50870300_21_dialog_content = "There was nothing to be offended about, Nikinis. In fact, I happen to agree with you. When a space is too clean, it can be somewhat unsettling.",
  ui_story_5087_50870300_22_dialog_content = "A palace should have more signs of life, like candle smoke and discarded tea leaves. Perhaps I can ask Noah and the others to assist me with this.",
  ui_story_5087_50870300_23_dialog_content = "Th-That wasn't what I meant, Your Majesty...",
  ui_story_5087_50870300_24_dialog_content = "I think the queen is telling us we should visit more often, sister.",
  ui_story_5087_50870300_25_dialog_content = "If we attend Her Majesty's reading club and afternoon tea sessions, we'll add more \"signs of life\" to the palace!",
  ui_story_5087_50870300_26_dialog_content = "Careful, Nepolis! Don't burn yourself so badly over something like tea...",
  ui_story_5087_50870300_27_dialog_content = "Heheh... My sister can be so adorable sometimes. Wouldn't you agree, Your Majesty?",
  ui_story_5087_50870300_28_dialog_content = "Nepolis!",
  ui_story_5087_50870300_29_dialog_content = "As sisters, the two of you couldn't be any closer. Your bond grants you both strength and unity, and that is the reason you were able to retrieve the Northland Mirror.",
  ui_story_5087_50870300_30_dialog_content = "Your work is greatly appreciated, Nepolis and Nikinis.",
  ui_story_5087_50870300_31_dialog_content = "We were just doing our duty to keep Northland safe.",
  ui_story_5087_50870300_32_dialog_content = "Your Majesty, may I ask... what happened to that mirror?",
  ui_story_5087_50870300_33_dialog_content = "The Northland Mirror can convert whatever it reflects into power, which is then transformed into monsters made of shadows.",
  ui_story_5087_50870300_34_dialog_content = "I have sealed away both the mirror and the monster dwelling within it. It poses no threat for the time being.",
  ui_story_5087_50870300_35_dialog_content = "We still have much to investigate with regard to its theft though. Tell me, did you notice anything unusual in the place where you found it?",
  ui_story_5087_50870300_36_dialog_content = "... In truth, everything about the scene was unusual.",
  ui_story_5087_50870300_37_dialog_content = "There was no one else in the cottage where the mirror was hidden, or any sign of the thief for that matter...",
  ui_story_5087_50870300_38_dialog_content = "When we entered the cottage, the mirror had already been shattered. There were no clues as to who shattered it or why they did so...",
  ui_story_5087_50870300_39_dialog_content = "The floor was littered with the mirror's broken fragments, and soon several beams of darkness escaped from them. They were very much like the shadowy monsters you just described, Your Majesty...",
  ui_story_5087_50870300_40_dialog_content = "Nikinis said she saw a mysterious figure in the mirror as well.",
  ui_story_5087_50870300_41_dialog_content = "...",
  ui_story_5087_50870300_42_dialog_content = "Shadowy monsters and a mysterious figure... I fear these are all products of the Northland Mirror's power.",
  ui_story_5087_50870300_43_dialog_content = "It's likely that the thief accidentally activated the mirror by getting caught in its reflection.",
  ui_story_5087_50870300_44_dialog_content = "If what you said is true, sealing the mirror itself will not be enough to ensure the kingdom's safety.",
  ui_story_5087_50870300_45_dialog_content = "I fear that the mirror shards also contain portions of those monsters' power. For the safety of our people, they must all be retrieved.",
  ui_story_5087_50870300_46_dialog_content = "May I entrust the two of you with this mission as well?",
  ui_story_5087_50870300_47_dialog_content = "Of course, Your Majesty! We're grateful for any chance to serve you.",
  ui_story_5087_50870300_48_dialog_content = "Your Majesty... May I ask you a question?",
  ui_story_5087_50870300_49_dialog_content = "By all means.",
  ui_story_5087_50870300_50_dialog_content = "Something about that mirror felt incredibly familiar, as though we had seen each other long ago...",
  ui_story_5087_50870300_51_dialog_content = "Could you explain why it felt that way to me?",
  ui_story_5087_50870300_52_dialog_content = "Really? That's odd. I didn't feel anything like that at all.",
  ui_story_5087_50870300_53_dialog_content = "... There appears to be no use in hiding it from you, Nikinis.",
  ui_story_5087_50870300_54_dialog_content = "Your intuition is entirely correct. You did encounter the Northland Mirror once before.",
  ui_story_5087_50870300_55_dialog_content = "I knew it!",
  ui_story_5087_50870300_56_dialog_content = "It happened when the two of you fell ill.",
  ui_story_5087_50870300_57_dialog_content = "At the time, Nepolis was beset by a terrible fever, yet you were perfectly healthy. Over time, however, you began to show similar symptoms.",
  ui_story_5087_50870300_58_dialog_content = "The two of you have always been this way. Your connection of body and soul makes you twice as powerful, but also twice as vulnerable.",
  ui_story_5087_50870300_59_dialog_content = "Your parents desperately sought the aid of several doctors, but all to no avail. Eventually, they had no choice but to bring you to the palace and ask for my assistance.",
  ui_story_5087_50870300_60_dialog_content = "To prevent any disruptions to your recovery, my first choice of action was to temporarily sever your connection.",
  ui_story_5087_50870300_61_dialog_content = "To that end, I required a powerful relic capable of influencing the souls of living beings—",
  ui_story_5087_50870300_62_dialog_content = "The Northland Mirror!",
  ui_story_5087_50870300_63_dialog_content = "Precisely. At the time, you showed an extremely high affinity for the Northland Mirror.",
  ui_story_5087_50870300_64_dialog_content = "That's also why I could successfully separate the two of you and cure your illnesses.",
  ui_story_5087_50870300_65_dialog_content = "...",
  ui_story_5087_50870300_66_dialog_content = "I see... I think I vaguely recall our parents bringing us to the Winter Palace for treatment...",
  ui_story_5087_50870300_67_dialog_content = "That's why it felt so familiar! I owe that mirror my life...",
  ui_story_5087_50870300_68_dialog_content = "... That is the truth of the matter. And now that you remember, I have no reason to deny it.",
  ui_story_5087_50870300_69_dialog_content = "But there is one thing you must always remember—never approach the mirror, and never believe the words spoken by its reflections.",
  ui_story_5087_50870300_70_dialog_content = "As one of the oldest and most powerful relics of Northland, it is surrounded by danger and mystery in equally high measures.",
  ui_story_5087_50870300_71_dialog_content = "Even the ancient civilizations, who were capable of creating marvels such as the Beacon and the Colossi—",
  ui_story_5087_50870300_72_dialog_content = "They were eons away from fully comprehending the mirror's power.",
  ui_story_5087_50870400_1_dialog_content = "Begone, monsters!",
  ui_story_5087_50870400_2_dialog_content = "Graaah...",
  ui_story_5087_50870400_3_dialog_content = "Not bad! At this rate, we'll find the rest of the mirror's fragments in no time, and our mission will be complete.",
  ui_story_5087_50870400_4_dialog_content = "... And it's all thanks to your ability to sense the mirror's presence.",
  ui_story_5087_50870400_5_dialog_content = "I'm just glad I can finally be helpful, Nepolis! In fact, let me go see if there are any more fragments nearby.",
  ui_story_5087_50870400_6_dialog_content = "... Sure. I'm counting on you.",
  ui_story_5087_50870400_7_dialog_content = "Huh? What's the matter, Nepolis? You seem a little glum.",
  ui_story_5087_50870400_8_dialog_content = "N-Not at all! If anything, you're the one who's acting differently! What's gotten into you?",
  ui_story_5087_50870400_9_dialog_content = "Guess there's no hiding it from you.",
  ui_story_5087_50870400_10_dialog_content = "Do you remember what Queen Bethlehem told us about the Northland Mirror?",
  ui_story_5087_50870400_11_dialog_content = "Of course. She said that the mirror's powers aren't just limited to creating monsters...",
  ui_story_5087_50870400_12_dialog_content = "It can use anything caught in its reflection to create realistic illusions, which can then influence people down to their very souls.",
  ui_story_5087_50870400_13_dialog_content = "Because it was created by an unknown civilization ages ago, the mirror contains an overwhelming and primal power...",
  ui_story_5087_50870400_14_dialog_content = "Neither the queen nor the civilizations from before our time could fully comprehend it...",
  ui_story_5087_50870400_15_dialog_content = "Even the most heretical organizations of Northland, the ones that are experts on ancient relics like this, are totally baffled by its magic.",
  ui_story_5087_50870400_16_dialog_content = "In order to unlock the full potential of such a powerful relic, a suitable host as its vessel is required...",
  ui_story_5087_50870400_17_dialog_content = "But becoming its host yields a far higher chance of dying before attaining its power.",
  ui_story_5087_50870400_18_dialog_content = "Nepolis... Despite how dangerous this mirror can be, Queen Bethlehem took the risk of using it to save us...",
  ui_story_5087_50870400_19_dialog_content = "Now that we know the truth, it's our turn to repay her... But up until now, all I've done is rely on your strength.",
  ui_story_5087_50870400_20_dialog_content = "With my ability to sense the mirror's presence, I can finally help you—",
  ui_story_5087_50870400_21_dialog_content = "... Stop!",
  ui_story_5087_50870400_22_dialog_content = "N-Nepolis?",
  ui_story_5087_50870400_23_dialog_content = "We can't rely on your affinity with the mirror too much, or let your soul get too close to it.",
  ui_story_5087_50870400_24_dialog_content = "\"Whoever is chosen by the mirror to become its host has a higher chance of dying before obtaining its power.\" Have you already forgotten what the queen told us?",
  ui_story_5087_50870400_25_dialog_content = "We need to hurry up and collect the remaining fragments, and then you're not allowed to go anywhere near it ever again.",
  ui_story_5087_50870400_26_dialog_content = "After our mission is over, we can finally go home to our field of flowers. We'll be safe, and our hearts and minds will be one again...",
  ui_story_5087_50870400_27_dialog_content = "O-Of course! I won't rashly get close to the mirror anymore, I promise!",
  ui_story_5087_50870400_28_dialog_content = "... And if we do have to get close to it, let me go in your place. After all, I don't have an affinity with it.",
  ui_story_5087_50870400_29_dialog_content = "Every time we talk about the mirror, it feels like you're getting further from me...",
  ui_story_5087_50870400_30_dialog_content = "Graah!",
  ui_story_5087_50870400_31_dialog_content = "Nepolis! The mirror's monsters are coming from over here too!",
  ui_story_5087_50870400_32_dialog_content = "Move, Nikinis!",
  ui_story_5087_50870400_33_dialog_content = "Leave the forest to me! ... Huh? Why does that one look different from the rest?",
  ui_story_5087_50870400_34_dialog_content = "Hold it right there, monster!",
  ui_story_5087_50870400_35_dialog_content = "Where did it go?",
  ui_story_5087_50870400_36_dialog_content = "(That wasn't an illusion just now. It looked like it was made out of ice crystals... Could this be the work of the Northland Mirror too?)",
  ui_story_5087_50870400_37_dialog_content = "<color=#e8d9bb>Suddenly, a rustling can be heard from deeper in the forest.</color>",
  ui_story_5087_50870400_38_dialog_content = "(... It's coming!)",
  ui_story_5087_50870400_39_dialog_content = "...",
  ui_story_5087_50870400_40_dialog_content = "A-A little girl?",
  ui_story_5087_50870501_1_dialog_content = "Good afternoon.",
  ui_story_5087_50870501_2_dialog_content = "(This child looks totally calm...)",
  ui_story_5087_50870501_3_dialog_content = "What are you doing all alone in the forest, little girl? Is your home close by?",
  ui_story_5087_50870501_4_dialog_content = "I'm... selling things.",
  ui_story_5087_50870501_5_dialog_content = "Oh, yeah, you're carrying a flower basket. Is that what you're selling?",
  ui_story_5087_50870501_6_dialog_content = "I have other items for sale too, but I haven't conducted any business yet. As such, I'm not ready to go home.",
  ui_story_5087_50870501_7_dialog_content = "\"As such\"? Heheh, for someone so young, you sure know how to speak like an adult. I'm impressed!",
  ui_story_5087_50870501_8_dialog_content = "I-I learned it from my mom and dad!",
  ui_story_5087_50870501_9_dialog_content = "Don't worry, I'm not a bad person. The forest can be a dangerous place, you know? There's even a monster on the loose right now.",
  ui_story_5087_50870501_10_dialog_content = "Do you know how to get home? I can escort you back, if you'd like.",
  ui_story_5087_50870501_11_dialog_content = "I'm not afraid of monsters.",
  ui_story_5087_50870501_12_dialog_content = "I-Is that so? I think you should at least be a little afraid of them...",
  ui_story_5087_50870501_13_dialog_content = "The only thing I fear is not being able to help my family with their burden. So, could you help me by purchasing something, miss?",
  ui_story_5087_50870501_14_dialog_content = "Like this hand mirror, for instance. Isn't it just lovely?",
  ui_story_5087_50870501_15_dialog_content = "!",
  ui_story_5087_50870501_16_dialog_content = "(Wait, I think it's just an ordinary mirror. Thank goodness... Still, I don't think Nepolis would appreciate it if I came back with a mirror.)",
  ui_story_5087_50870501_17_dialog_content = "I'm sorry, dear, but I've had a lot of bad luck with mirrors lately.",
  ui_story_5087_50870501_18_dialog_content = "... I see.",
  ui_story_5087_50870501_19_dialog_content = "Then... How about some freshly-cut flowers? Would you be willing to buy a few?",
  ui_story_5087_50870501_20_dialog_content = "See? I have yellow roses, forget-me-nots, and even some white narcissuses! One of these must catch your eye, right?",
  ui_story_5087_50870501_21_dialog_content = "What a coincidence! I happen to love all of these flowers the most!",
  ui_story_5087_50870501_22_dialog_content = "I'm happy to hear that, miss.",
  ui_story_5087_50870501_23_dialog_content = "Then you must know what they <color=#FFB400>symbolize</color>, yes?",
  ui_story_5087_50870501_24_dialog_content = "What they symbolize...",
  ui_story_5087_50870501_25_dialog_content = "More flowers? How kind of you, Nikinis. Now then, what have you brought me today? Yellow roses and forget-me-nots?",
  ui_story_5087_50870501_26_dialog_content = "Yes, Your Majesty. I've always wanted to present you with these flowers because of what they symbolize—",
  ui_story_5087_50870501_27_dialog_content = "(That memory I saw in my mind just now... When did that happen?)",
  ui_story_5087_50870501_28_dialog_content = "(When I look at this little girl... why do I suddenly remember the queen?)",
  ui_story_5087_50870501_29_dialog_content = "... Nikinis! Watch out!",
  ui_story_5087_50870501_30_dialog_content = "Graaah!",
  ui_story_5087_50870501_31_dialog_content = "Get behind me, little girl!",
  ui_story_5087_50870501_32_dialog_content = "I'm afraid I can't do that.",
  ui_story_5087_50870501_33_dialog_content = "No matter where I am, I must help my family with their burden.",
  ui_story_5087_50870502_1_dialog_content = "You can use Luminatics?",
  ui_story_5087_50870502_2_dialog_content = "And skillfully, at that...",
  ui_story_5087_50870502_3_dialog_content = "This is hardly uncommon here in Northland.",
  ui_story_5087_50870502_4_dialog_content = "You were trying to protect me just now, weren't you? Thank you, please have these flowers as a token of my gratitude. Farewell!",
  ui_story_5087_50870502_5_dialog_content = "Wait, come back! I can't just take these for free... At least tell me your name!",
  ui_story_5087_50870502_6_dialog_content = "Shaya. My name is Shaya.",
  ui_story_5087_50870502_7_dialog_content = "Nikinis—",
  ui_story_5087_50870502_8_dialog_content = "Are you okay? That monster didn't hurt you, did it? And who were you talking to just now?",
  ui_story_5087_50870502_9_dialog_content = "I'm fine, Nepolis. I met a little girl selling flowers in the forest, and she gave me a bouquet for helping her. See?",
  ui_story_5087_50870502_10_dialog_content = "That's great since they're all your favorite flowers.",
  ui_story_5087_50870502_11_dialog_content = "You've never liked crowds, and you would always slip away from the Winter Palace during banquets, even the ones meant for you...",
  ui_story_5087_50870502_12_dialog_content = "But every time, the people you helped would find you and give you flowers! Beautiful bouquets of white narcissuses and lilies.",
  ui_story_5087_50870502_13_dialog_content = "I'm sure that little girl was also... Huh?",
  ui_story_5087_50870502_14_dialog_content = "This bouquet only has white narcissuses in it...",
  ui_story_5087_50870502_15_dialog_content = "!",
  ui_story_5087_50870502_16_dialog_content = "Come on, Nikinis. Let's make sure there aren't any more mirror fragments around here before we report back to the Winter Palace.",
  ui_story_5087_50870502_17_dialog_content = "(Is Nepolis... sulking? That's odd, I don't think I've ever seen this side of her.)",
  ui_story_5087_50870502_18_dialog_content = "(I'll just put one of these flowers in her hair. That way, the white narcissus and the lily will be together again.)",
  ui_story_5087_50870502_19_dialog_content = "Hmm? There's something hard tucked inside this bouquet...",
  ui_story_5087_50870502_20_dialog_content = "It's that hand mirror!",
  ui_story_5087_50870502_21_dialog_content = "(Did Shaya do this on purpose? Did she stuff this mirror into the bouquet because I refused to buy it?)",
  ui_story_5087_50870502_22_dialog_content = "(Why was she so intent on giving this to me?)",
  ui_story_5087_50870502_23_dialog_content = "Nikinis... Nikinis...",
  ui_story_5087_50870502_24_dialog_content = "(It's him again! The voice from the Northland Mirror! He can appear in other mirrors too?)",
  ui_story_5087_50870502_25_dialog_content = "(This is bad, I promised Nepolis I wouldn't go near any suspicious-looking mirrors...)",
  ui_story_5087_50870502_26_dialog_content = "Nikinis... Can you hear me?",
  ui_story_5087_50870502_27_dialog_content = "...",
  ui_story_5087_50870502_28_dialog_content = "Yes, but who are you? Why do you keep appearing inside of mirrors?",
  ui_story_5087_50870502_29_dialog_content = "Excellent, the mirror finally made its way into your hands... Please... Don't tell anyone about this!",
  ui_story_5087_50870600_1_dialog_content = "<color=#e8d9bb>Night falls, and a howling blizzard blankets the sky in snow. Even the shadows of flames inside the fireplace seem to flicker with unease.</color>",
  ui_story_5087_50870600_2_dialog_content = "(I wonder how our parents are weathering a storm like this... Surely they wouldn't stay outdoor for nights like this, I guess?)",
  ui_story_5087_50870600_3_dialog_content = "I'm finally done reporting everything to the queen, Nikinis! She was really pleased with our results!",
  ui_story_5087_50870600_4_dialog_content = "That's wonderful. Now we can finally go home and spend some time with our parents.",
  ui_story_5087_50870600_5_dialog_content = "Oh... Right...",
  ui_story_5087_50870600_6_dialog_content = "Nepolis! Nikinis! Oh, thank goodness you haven't left yet!",
  ui_story_5087_50870600_7_dialog_content = "A letter just came in from your parents. They said they're still carrying out the queen's orders, so they won't be able to return for a few more days.",
  ui_story_5087_50870600_8_dialog_content = "In a storm like this, it's best if you don't go back right now either. Wouldn't want to get trapped in the snow, right?",
  ui_story_5087_50870600_9_dialog_content = "B-But...",
  ui_story_5087_50870600_10_dialog_content = "He has a point, Nikinis. Trying to navigate this blizzard at night would be way too dangerous.",
  ui_story_5087_50870600_11_dialog_content = "Besides, our parents aren't even home right now. Let's just spend the night somewhere nearby, okay?",
  ui_story_5087_50870600_12_dialog_content = "If you say so...",
  ui_story_5087_50870600_13_dialog_content = "(I don't recall seeing our parents at the Winter Palace before... Could this be an aftereffect of my illness?)",
  ui_story_5087_50870600_14_dialog_content = "(If they had been working for the queen, surely Nepolis and I would have seen them at the palace, right?)",
  ui_story_5087_50870600_15_dialog_content = "(But are they really carrying out the queen's orders? When did they start doing that? Why don't I remember anything about it?)",
  ui_story_5087_50870600_16_dialog_content = "(The only thing I can clearly recall is them bringing us to the Winter Palace for treatment.)",
  ui_story_5087_50870600_17_dialog_content = "(After that, I could barely even remember their faces...)",
  ui_story_5087_50870600_18_dialog_content = "(Could it be that my illness affected my memories somehow?)",
  ui_story_5087_50870600_19_dialog_content = "(Even though I don't recall any of this, Nepolis and that messenger are talking about it like it's completely normal. It almost feels like...)",
  ui_story_5087_50870600_20_dialog_content = "(This world is shrouded in a layer of illusion.)",
  ui_story_5087_50870600_21_dialog_content = "(No... I must be imagining things. My sister is real, no doubt about it.)",
  ui_story_5087_50870600_22_dialog_content = "... Ah!",
  ui_story_5087_50870600_23_dialog_content = "What is it, Nepolis?",
  ui_story_5087_50870600_24_dialog_content = "My hair! It got caught in one of the tree branches! Help me, Nikinis!",
  ui_story_5087_50870600_25_dialog_content = "Honestly... How did you get it stuck in a branch? Stop squirming around before you hurt yourself!",
  ui_story_5087_50870600_26_dialog_content = "It's because I saw a cute little squirrel just now. I walked over to get a closer look, but then...",
  ui_story_5087_50870600_27_dialog_content = "You managed to do some pretty incredible things when I was not paying attention, you know?",
  ui_story_5087_50870600_28_dialog_content = "You're one to talk, Nikinis. You've been discovering all kinds of powers and emotions lately, all without me noticing...",
  ui_story_5087_50870600_29_dialog_content = "We used to be one and the same, remember? Our hearts and souls were connected, and we shared everything from our looks and talents to our likes and dislikes.",
  ui_story_5087_50870600_30_dialog_content = "Watching you slowly become someone else makes me feel so lonely at times...",
  ui_story_5087_50870600_31_dialog_content = "See the bouquet you got—narcissuses are tied closely with yellow roses and forget-me-nots, but without any lilies...",
  ui_story_5087_50870600_32_dialog_content = "Nepolis... What in the world are you talking about? There isn't another pair of siblings in the world more alike than the two of us! When did we become \"different\" to you?",
  ui_story_5087_50870600_33_dialog_content = "I promised never to go near that mirror again, so please don't worry about me, okay?",
  ui_story_5087_50870600_34_dialog_content = "... There! Your hair is untangled now. Come out from under that tree.",
  ui_story_5087_50870600_35_dialog_content = "Sweet, sweet freedom!",
  ui_story_5087_50870600_36_dialog_content = "... Thank you, Nikinis. Without you, I don't know what I would do.",
  ui_story_5087_50870600_37_dialog_content = "So, just stop saying things like \"I'm no help to my sister...\"",
  ui_story_5087_50870600_38_dialog_content = "Having you by my side is the greatest blessing I could ever ask for.",
  ui_story_5087_50870600_39_dialog_content = "(Nepolis is real, and so am I. There's no question about it.)",
  ui_story_5087_50870600_40_dialog_content = "(That's why... I have to destroy this mysterious mirror.)",
  ui_story_5087_50870600_41_dialog_content = "Nikinis... Is that you?",
  ui_story_5087_50870600_42_dialog_content = "(... He's back again!)",
  ui_story_5087_50870600_43_dialog_content = "Please don't talk to me anymore. I don't want my sister to keep suffering like this!",
  ui_story_5087_50870600_44_dialog_content = "Just listen to me, Nikinis! You have to go... and find... only then...",
  ui_story_5087_50870600_45_dialog_content = "Go where? What am I supposed to find?",
  ui_story_5087_50870600_46_dialog_content = "Who are you, and why do you keep talking to me through mirrors?",
  ui_story_5087_50870600_47_dialog_content = "I am... You're in a... Only by... can you...",
  ui_story_5087_50870600_48_dialog_content = "... I can't understand anything you're saying. Your voice keeps fading away at the worst time!",
  ui_story_5087_50870600_49_dialog_content = "It's that thing! It keeps interfering with us! Even after breaking the... it never stopped. It's still blocking... Urgh!",
  ui_story_5087_50870600_50_dialog_content = "\"Breaking\"? Are you talking about the Northland Mirror? Do you know who did it? Wait, how do you know about the mirror being broken?",
  ui_story_5087_50870600_51_dialog_content = "Could it be... that you were the one who stole the Northland Mirror?",
  ui_story_5087_50870600_52_dialog_content = "<color=#e8d9bb>Before the person in the mirror can answer, the blizzard slams even harder into the cottage, rattling the windows in their frames.</color>",
  ui_story_5087_50870600_53_dialog_content = "<color=#e8d9bb>Nikinis lowers her head once again. The mirror in her hands reflects nothing but the flickering flames of the fireplace and the swirling snow outside.</color>",
  ui_story_5087_50870700_1_dialog_content = "<color=#e8d9bb>Snow continues to fall as shadowy clouds loom over Northland, their dark and solemn appearance directly reflecting Nikinis' mood.</color>",
  ui_story_5087_50870700_2_dialog_content = "<color=#e8d9bb>An unreachable home, an unsolvable mystery, and an uncertain memory... All of these things weigh heavily on her heart.</color>",
  ui_story_5087_50870700_3_dialog_content = "<color=#e8d9bb>Her only glimmer of hope is the mirror in her hands, which she nearly destroyed.</color>",
  ui_story_5087_50870700_4_dialog_content = "(The person in the mirror doesn't seem to be returning anytime soon...)",
  ui_story_5087_50870700_5_dialog_content = "(Is someone really interfering with our communication? Maybe it's the person who broke the mirror in the first place.)",
  ui_story_5087_50870700_6_dialog_content = "(The person in the mirror wants me to do something... But why? Are they fighting with whoever broke the mirror? The questions never seem to end...)",
  ui_story_5087_50870700_7_dialog_content = "Nikinis! We've got trouble!",
  ui_story_5087_50870700_8_dialog_content = "Wh-What is it?",
  ui_story_5087_50870700_9_dialog_content = "Huh? Why do you look so flustered? Don't tell me you got a love letter or something.",
  ui_story_5087_50870700_10_dialog_content = "Not at all! Even if I did, I wouldn't hide it from you—",
  ui_story_5087_50870700_11_dialog_content = "I'd never let you worry about something like that, Nepolis. Trust me.",
  ui_story_5087_50870700_12_dialog_content = "... You don't have to defend yourself like this, you know? Your love letters are your own business, after all.",
  ui_story_5087_50870700_13_dialog_content = "There is no love letter!",
  ui_story_5087_50870700_14_dialog_content = "O-Okay, I believe you! Now just listen to me, something really big just happened—",
  ui_story_5087_50870700_15_dialog_content = "The queen just published a portrait of the mirror thief!",
  ui_story_5087_50870700_16_dialog_content = "What? Where?",
  ui_story_5087_50870700_17_dialog_content = "Oh? I didn't expect you would be so concerned about it. Come with me.",
  ui_story_5087_50870700_18_dialog_content = "Queen Bethlehem has uncovered the identity of the thief and has posted a portrait of them for all to see.",
  ui_story_5087_50870700_19_dialog_content = "Starting today, Northland's borders will be sealed off, and its forces will be focused on the thief's capture. All residents of Northland are encouraged to report any suspicious activity right away!",
  ui_story_5087_50870700_20_dialog_content = "They're closing off the borders? Her Majesty rarely mobilizes the kingdom like this...",
  ui_story_5087_50870700_21_dialog_content = "Didn't you see what happened this morning? The Winter Palace practically dispatched an army to hunt down this thief!",
  ui_story_5087_50870700_22_dialog_content = "Makes sense to me. After all, not just anyone can sneak their way into the Winter Palace's treasure vault.",
  ui_story_5087_50870700_23_dialog_content = "Even just one piece of those relics is powerful enough to level a hundred villages. The queen is only doing this for our sake.",
  ui_story_5087_50870700_24_dialog_content = "Take a look at this portrait—apparently the thief is a little girl! How did a child manage to break into the Winter Palace?",
  ui_story_5087_50870700_25_dialog_content = "(A little girl? Don't tell me...)",
  ui_story_5087_50870700_26_dialog_content = "Pardon me! Coming through—",
  ui_story_5087_50870700_27_dialog_content = "(I knew it... It was her!)",
  ui_story_5087_50870700_28_dialog_content = "You're surprised too, aren't you Nikinis? As it turns out, Northland's most wanted thief is just a cute little girl...",
  ui_story_5087_50870700_29_dialog_content = "I-I have to go, Nepolis!",
  ui_story_5087_50870700_30_dialog_content = "Huh? Wait, Nikinis, the queen tasked us with another mission—",
  ui_story_5087_50870700_31_dialog_content = "Hey! Are you in there? Please say something!",
  ui_story_5087_50870700_32_dialog_content = "(No response... How did I make the person in the mirror appear last time? That's right! It was when I thought about using Luminatics to destroy it!)",
  ui_story_5087_50870700_33_dialog_content = "(I'll try infusing the mirror with Lumina first...)",
  ui_story_5087_50870700_34_dialog_content = "Nikinis!",
  ui_story_5087_50870700_35_dialog_content = "You're here! Tell me, are you working with a little girl named Shaya?",
  ui_story_5087_50870700_36_dialog_content = "You two were the ones who stole the Northland Mirror, weren't you?",
  ui_story_5087_50870700_37_dialog_content = "... That's right. Shaya is actually... Because she... and entered... on her own...",
  ui_story_5087_50870700_38_dialog_content = "The Northland Mirror is the passageway we prepared for you... but it was broken by...",
  ui_story_5087_50870700_39_dialog_content = "It must be restored first... which is why we need your help.",
  ui_story_5087_50870700_40_dialog_content = "We sent Shaya to deliver this mirror to you, so we could communicate.",
  ui_story_5087_50870700_41_dialog_content = "What are you talking about? Tell me what you're planning!",
  ui_story_5087_50870700_42_dialog_content = "I can't answer you right now. Whenever I try to tell you something... blocked.",
  ui_story_5087_50870700_43_dialog_content = "Find Shaya, and she will tell you everything... Only she can help you now!",
  ui_story_5087_50870700_44_dialog_content = "<color=#e8d9bb>The person in the mirror disappears with a flash.</color>",
  ui_story_5087_50870700_45_dialog_content = "(Her Majesty's judgment wasn't wrong after all... The one who stole the Northland Mirror was Shaya.)",
  ui_story_5087_50870700_46_dialog_content = "(Not only that, she and the person in the mirror are plotting something together.)",
  ui_story_5087_50870700_47_dialog_content = "(But why? I didn't sense any animosity from Shaya or this mirror...)",
  ui_story_5087_50870700_48_dialog_content = "...",
  ui_story_5087_50870700_49_dialog_content = "(I'll keep the mirror out of sight for now. Nepolis will be back any second.)",
  ui_story_5087_50870700_50_dialog_content = "(I can't believe I'm keeping such a big secret from her... By trusting the mirror, am I putting more distance between us?)",
  ui_story_5087_50870700_51_dialog_content = "Nikinis! How could you run off on your own like that?",
  ui_story_5087_50870700_52_dialog_content = "... I'm sorry.",
  ui_story_5087_50870700_53_dialog_content = "The queen has ordered us to capture the mirror thief! There's no time to waste, so grab your coat and boots—",
  ui_story_5087_50870700_54_dialog_content = "Oh! Sorry, I'll be right there! Thank you for letting me know... Sorry for running away just now.",
  ui_story_5087_50870700_55_dialog_content = "... Why are you apologizing so much? We're sisters, remember?",
  ui_story_5087_50870700_56_dialog_content = "You're the most important person in my life. No matter what happens, that'll never change.",
  ui_story_5087_50870800_1_dialog_content = "I'll go check over there, Nepolis.",
  ui_story_5087_50870800_2_dialog_content = "Then I'll look over here. Stay on your guard.",
  ui_story_5087_50870800_3_dialog_content = "I'll be fine. Besides, I know you'll come to my rescue as soon as you sense that I'm in trouble.",
  ui_story_5087_50870800_4_dialog_content = "As twins, we're connected in mind and soul, remember?",
  ui_story_5087_50870800_5_dialog_content = "...",
  ui_story_5087_50870800_6_dialog_content = "(This place should be safe enough.)",
  ui_story_5087_50870800_7_dialog_content = "Hey, are you there?",
  ui_story_5087_50870800_8_dialog_content = "What is it, Nikinis? Did you manage to find Shaya?",
  ui_story_5087_50870800_9_dialog_content = "Not yet, no. My sister and I are searching for her as we speak, along with the rest of the kingdom.",
  ui_story_5087_50870800_10_dialog_content = "I can't remember a time in which the whole Northland was mobilized to hunt down a single thief. Something about this world doesn't seem right after all...",
  ui_story_5087_50870800_11_dialog_content = "That's because you're... Don't worry about Shaya though. After all, she is... Ordinary people shouldn't pose a threat to her.",
  ui_story_5087_50870800_12_dialog_content = "Listen to me, mirror! I...",
  ui_story_5087_50870800_13_dialog_content = "I want to tell my sister everything I know about you and Shaya...",
  ui_story_5087_50870800_14_dialog_content = "Huh? I... I don't know if that's a good idea...",
  ui_story_5087_50870800_15_dialog_content = "My sister and I are one and the same.",
  ui_story_5087_50870800_16_dialog_content = "Huh?",
  ui_story_5087_50870800_17_dialog_content = "Ever since we came into the world, we've always been together. Like two flowers planted alongside one another, we grew and bloomed in the exact same way.",
  ui_story_5087_50870800_18_dialog_content = "I can't explain why, but I know you and Shaya aren't bad people. Maybe it's just my intuition...",
  ui_story_5087_50870800_19_dialog_content = "And if it is, my sister will share the same intuition as my own. No matter what you're planning, she won't stand in your way.",
  ui_story_5087_50870800_20_dialog_content = "In fact, she'll help you.",
  ui_story_5087_50870800_21_dialog_content = "... Are you really so sure?",
  ui_story_5087_50870800_22_dialog_content = "Positive. That's because I'm already considering the same.",
  ui_story_5087_50870800_23_dialog_content = "I only need to look into my own heart to know what my sister's choice will be.",
  ui_story_5087_50870800_24_dialog_content = "... I understand.",
  ui_story_5087_50870800_25_dialog_content = "I do have one more request. Queen Bethlehem is the one who ordered Shaya's capture, which means she must know something.",
  ui_story_5087_50870800_26_dialog_content = "Would it be alright if I also told her about—",
  ui_story_5087_50870800_27_dialog_content = "Absolutely not!",
  ui_story_5087_50870800_28_dialog_content = "?",
  ui_story_5087_50870800_29_dialog_content = "That \"Queen Bethlehem\" is... She's not... so you can't...",
  ui_story_5087_50870800_30_dialog_content = "I can't hear what you're saying. I think the interference is getting worse.",
  ui_story_5087_50870800_31_dialog_content = "Urgh! How am I supposed to tell you... Don't believe... Fake!",
  ui_story_5087_50870800_32_dialog_content = "What's fake? The letter from that messenger? The story about my parents? My memories?",
  ui_story_5087_50870800_33_dialog_content = "Or could it be... the queen?",
  ui_story_5087_50870800_34_dialog_content = "Yes!",
  ui_story_5087_50870800_35_dialog_content = "Her Majesty is a fake?",
  ui_story_5087_50870800_36_dialog_content = "Yes! It's true! She... Her goal is...",
  ui_story_5087_50870800_37_dialog_content = "... Stop right there!",
  ui_story_5087_50870800_38_dialog_content = "?",
  ui_story_5087_50870800_39_dialog_content = "Urgh!",
  ui_story_5087_50870800_40_dialog_content = "I finally caught you! Let's see you run away now! ",
  ui_story_5087_50870800_41_dialog_content = "What is it, Nepolis? Ah! It's you... Shaya...",
  ui_story_5087_50870800_42_dialog_content = "I caught this little sneak thief stalking you from the trees. She was definitely up to something sinister!",
  ui_story_5087_50870800_43_dialog_content = "But don't worry, I caught her before she could make her move! You're safe now!",
  ui_story_5087_50870800_44_dialog_content = "...",
  ui_story_5087_50870800_45_dialog_content = "Nikinis... Help me...",
  ui_story_5087_50870800_46_dialog_content = "What? Y-You know each other? When did that happen? And why wasn't I told about it?",
  ui_story_5087_50870800_47_dialog_content = "Nepolis... I'm so sorry.",
  ui_story_5087_50870800_48_dialog_content = "Ah! I wasn't blaming you—",
  ui_story_5087_50870800_49_dialog_content = "But don't worry, I'll tell you everything now. I won't hide anything from you ever again, I promise.",
  ui_story_5087_50870800_50_dialog_content = "After this... I'll need your wisdom.",
  ui_story_5087_50870900_1_dialog_content = "Queen Bethlehem is an imposter?",
  ui_story_5087_50870900_2_dialog_content = "Yes. She's nothing but an illusion of shadows, which is why her reaction is so aggressive.",
  ui_story_5087_50870900_3_dialog_content = "Mobilizing an entire kingdom to apprehend a single thief... is an extremely inefficient use of her power.",
  ui_story_5087_50870900_4_dialog_content = "The real queen would have thought of something much more ingenious.",
  ui_story_5087_50870900_5_dialog_content = "(Even after meeting her for the second time, I still think there's something unique about Shaya.)",
  ui_story_5087_50870900_6_dialog_content = "(Despite being such a young girl, she has a righteous air about her, and she has no qualms criticizing the queen.)",
  ui_story_5087_50870900_7_dialog_content = "It's true that Her Majesty's methods have been somewhat different lately, but that's hardly a reason to suspect her...",
  ui_story_5087_50870900_8_dialog_content = "If what you said is true, Shaya, then where is the real queen?",
  ui_story_5087_50870900_9_dialog_content = "... Generally speaking, Bethlehem tends to spend her time in a different world—the world on the other side of the Northland Mirror.",
  ui_story_5087_50870900_10_dialog_content = "... You're saying that there's an entirely different world behind the Northland Mirror?",
  ui_story_5087_50870900_11_dialog_content = "Does this mean your reason for stealing the mirror was to travel to this other world and find the real Queen Bethlehem?",
  ui_story_5087_50870900_12_dialog_content = "Your reasoning is on the right path... It's true, I do need to go over there.",
  ui_story_5087_50870900_13_dialog_content = "The Northland Mirror is the perfect passageway to travel between both worlds.",
  ui_story_5087_50870900_14_dialog_content = "But now that it's broken, it must be repaired before I can do so.",
  ui_story_5087_50870900_15_dialog_content = "Nikinis, you have a powerful affinity with the Northland Mirror. To restore it to its original state, I require your assistance.",
  ui_story_5087_50870900_16_dialog_content = "Are you willing to help me? Naturally, I would be willing to help the two of you as well.",
  ui_story_5087_50870900_17_dialog_content = "The one in the mirror can serve as your guide. He also exists in the other world, and his goal is no different than mine.",
  ui_story_5087_50870900_18_dialog_content = "...",
  ui_story_5087_50870900_19_dialog_content = "What do you think, Nepolis? I know you don't want me to go anywhere near that mirror.",
  ui_story_5087_50870900_20_dialog_content = "But you want to do this, don't you?",
  ui_story_5087_50870900_21_dialog_content = "I...",
  ui_story_5087_50870900_22_dialog_content = "... I'm sorry, Nikinis. It looks like my jealousy made you worry.",
  ui_story_5087_50870900_23_dialog_content = "I can tell that you've been thinking about me and my feelings for the last few days...",
  ui_story_5087_50870900_24_dialog_content = "Even though I'm the older one, I'm hardly acting like it.",
  ui_story_5087_50870900_25_dialog_content = "That's not it at all! You and I think exactly the same. All I want is to be with you in mind and soul, just like always...",
  ui_story_5087_50870900_26_dialog_content = "... It's what I want more than anything else in the world!",
  ui_story_5087_50870900_27_dialog_content = "But that doesn't give me the right to strip you of your wings.",
  ui_story_5087_50870900_28_dialog_content = "!",
  ui_story_5087_50870900_29_dialog_content = "...",
  ui_story_5087_50870900_30_dialog_content = "The truth is, I'm having a very difficult time believing everything you just told us, Shaya.",
  ui_story_5087_50870900_31_dialog_content = "... I understand.",
  ui_story_5087_50870900_32_dialog_content = "But my sister has always placed a great deal of importance on that mirror.",
  ui_story_5087_50870900_33_dialog_content = "After hearing the queen's story about how we were cured, I'm convinced that Nikinis and the mirror share an inextricable fate.",
  ui_story_5087_50870900_34_dialog_content = "I felt lonely because only my sister was chosen, and so I began acting out of envy...",
  ui_story_5087_50870900_35_dialog_content = "It was wrong of me to do that. As the older sister, I'm supposed to be looking after her and helping her grow.",
  ui_story_5087_50870900_36_dialog_content = "Nepolis...",
  ui_story_5087_50870900_37_dialog_content = "... You have quite an incredible soul, Nepolis.",
  ui_story_5087_50870900_38_dialog_content = "Perhaps I've been underestimating you all along.",
  ui_story_5087_50870900_39_dialog_content = "So, Shaya—",
  ui_story_5087_50870900_40_dialog_content = "Just tell us what we need to do to help you restore the Northland Mirror!",
  ui_story_5087_50871000_1_dialog_content = "...",
  ui_story_5087_50871000_2_dialog_content = "...",
  ui_story_5087_50871000_3_dialog_content = "Hmm... Once we cross this mountain, we should arrive at the Winter Palace.",
  ui_story_5087_50871000_4_dialog_content = "...",
  ui_story_5087_50871000_5_dialog_content = "...",
  ui_story_5087_50871000_6_dialog_content = "We can't just keep trudging along in silence! Shaya, I know you're very dissatisfied with the fake queen right now—",
  ui_story_5087_50871000_7_dialog_content = "I'm extremely dissatisfied, actually. She mobilized every soldier in the kingdom to hunt for a thief!",
  ui_story_5087_50871000_8_dialog_content = "Nepolis, I know you're still not convinced—",
  ui_story_5087_50871000_9_dialog_content = "Of course I'm not convinced!",
  ui_story_5087_50871000_10_dialog_content = "It's one thing to restore the Northland Mirror, or to sneak into the Winter Palace's treasure vault...",
  ui_story_5087_50871000_11_dialog_content = "But \"how to join our forces and defeat the queen if she discovers us\"? How dare you include that in your plan!",
  ui_story_5087_50871000_12_dialog_content = "You even made a drawing for this!",
  ui_story_5087_50871000_13_dialog_content = "How do you know the queen's weaknesses so well, Shaya? Are you sure you're not plotting anything else?",
  ui_story_5087_50871000_14_dialog_content = "... Now I understand the pain of not being able to tell the truth.",
  ui_story_5087_50871000_15_dialog_content = "Nikinis! Don't you remember the risk Her Majesty took to save our lives?",
  ui_story_5087_50871000_16_dialog_content = "I...",
  ui_story_5087_50871000_17_dialog_content = "How can you possibly believe every word this girl says about our queen being an imposter so easily?",
  ui_story_5087_50871000_18_dialog_content = "Nepolis, I commend you for being so loyal to Bethlehem—",
  ui_story_5087_50871000_19_dialog_content = "Stop addressing the queen by just her name!",
  ui_story_5087_50871000_20_dialog_content = "But even the real Bethlehem would be flabbergasted by your stubbornness right now.",
  ui_story_5087_50871000_21_dialog_content = "How dare you say that about Her Majesty! A dignified and noble queen like her would never—",
  ui_story_5087_50871000_22_dialog_content = "She would. Trust me.",
  ui_story_5087_50871000_23_dialog_content = "You two...",
  ui_story_5087_50871000_24_dialog_content = "I don't know why you're in such a rush either, Nikinis.",
  ui_story_5087_50871000_25_dialog_content = "Infiltrating the treasure vault requires careful planning and investigation. Besides, the Northland Mirror isn't going anywhere.",
  ui_story_5087_50871000_26_dialog_content = "Why do you insist on breaking in there today? And if the queen does find us, are you really prepared to fight her?",
  ui_story_5087_50871000_27_dialog_content = "That thing is not your queen.",
  ui_story_5087_50871000_28_dialog_content = "You're the only one who says so.",
  ui_story_5087_50871000_29_dialog_content = "Most of the Winter Palace's soldiers are out scouring the country for me right now. We won't have another chance like this to break into the vault.",
  ui_story_5087_50871000_30_dialog_content = "So you know we're \"breaking in\" too, don't you?",
  ui_story_5087_50871000_31_dialog_content = "Nepolis! Shaya! Stop your bickering right now!",
  ui_story_5087_50871000_32_dialog_content = "It's true, I am in a hurry to do this. But Nepolis, you have to understand that there's something terribly wrong with this world right now...",
  ui_story_5087_50871000_33_dialog_content = "...",
  ui_story_5087_50871000_34_dialog_content = "What exactly is wrong with it?",
  ui_story_5087_50871000_35_dialog_content = "Plenty of things... For instance, when did our parents start working for the Winter Palace? You and everyone else seem to know about it, yet I have no recollection of it at all...",
  ui_story_5087_50871000_36_dialog_content = "What? Could this be an aftereffect of your illness? Are you feeling unwell again?",
  ui_story_5087_50871000_37_dialog_content = "I...",
  ui_story_5087_50871000_38_dialog_content = "(What should I do? For the first time in my life... I don't know how to tell my sister what I'm thinking.)",
  ui_story_5087_50871000_39_dialog_content = "(She seems so concerned about me. Am I the one being too willful about this?)",
  ui_story_5087_50871000_40_dialog_content = "... I'm just glad you're okay. I'll just... go scout ahead for now.",
  ui_story_5087_50871000_41_dialog_content = "Neither of you is wrong, so please don't let it bother you. It's just that only you are capable of sensing certain things.",
  ui_story_5087_50871000_42_dialog_content = "But why... Why am I the only one who can feel them?",
  ui_story_5087_50871000_43_dialog_content = "My sister and I have always been the same. When did we... start to have these differences?",
  ui_story_5087_50871000_44_dialog_content = "Though they're both as pure and white as snow, a lily and a white narcissus will always be two different flowers. What's more...",
  ui_story_5087_50871000_45_dialog_content = "...",
  ui_story_5087_50871000_46_dialog_content = "Please tell me, Shaya! Is it just my imagination, or is there really something wrong with this world?",
  ui_story_5087_50871000_47_dialog_content = "Aside from the queen being fake, is there anything else you're not telling me?",
  ui_story_5087_50871000_48_dialog_content = "... There is.",
  ui_story_5087_50871000_49_dialog_content = "!",
  ui_story_5087_50871000_50_dialog_content = "But it would be unwise of me to tell you right now.",
  ui_story_5087_50871000_51_dialog_content = "Once we reach the Winter Palace and restore the mirror, everything will be made clear.",
  ui_story_5087_50871000_52_dialog_content = "You... You do not have a sister, do you?",
  ui_story_5087_50871000_53_dialog_content = "... I do.",
  ui_story_5087_50871000_54_dialog_content = "You do?",
  ui_story_5087_50871000_55_dialog_content = "Though even by the most generous standards, it's far from being considered a friendly relationship.",
  ui_story_5087_50871000_56_dialog_content = "So, I really envy Nepolis and you.",
  ui_story_5087_50871000_57_dialog_content = "... I want to protect the two of you, even if it's just for another second.",
  ui_story_5087_50871000_58_dialog_content = "You've got the wrong idea, Shaya.",
  ui_story_5087_50871000_59_dialog_content = "Huh?",
  ui_story_5087_50871000_60_dialog_content = "Even if my sister and I were born with a telepathic connection that granted us awareness of the other's thoughts—",
  ui_story_5087_50871000_61_dialog_content = "We still fight. You've seen it yourself.",
  ui_story_5087_50871000_62_dialog_content = "!",
  ui_story_5087_50871000_63_dialog_content = "But that is only temporary. It's just a little bit of friction that arises from a difference in feelings and experiences.",
  ui_story_5087_50871000_64_dialog_content = "The fact you envy the relationship we have is proof that you haven't given up on your own sisterly relationship...",
  ui_story_5087_50871000_65_dialog_content = "You still dream of patching things up with your sister.",
  ui_story_5087_50871000_66_dialog_content = "As long as you don't give up, one day, you will come to understand each other... at least that's what I believe.",
  ui_story_5087_50871000_67_dialog_content = "... Thank you, Nikinis. I'll keep that in mind.",
  ui_story_5087_50871000_68_dialog_content = "Nepolis refuses to make a move against the fake queen, so let's split up once we're inside the Winter Palace.",
  ui_story_5087_50871000_69_dialog_content = "I'll figure out how to deal with the queen. You just head straight for the treasure vault with your sister.",
  ui_story_5087_50871000_70_dialog_content = "I can't let you do that! Her Majesty's too strong—",
  ui_story_5087_50871000_71_dialog_content = "No, it's better like this. We'll stand out if we stick together.",
  ui_story_5087_50871000_72_dialog_content = "With the connection you two share, you make a much more efficient pair when you aren't dragging me along.",
  ui_story_5087_50871000_73_dialog_content = "I'll keep the queen busy in secret and cover you. It's easier to do that alone.",
  ui_story_5087_50871000_74_dialog_content = "Seek answers from the one in the mirror if you encounter any issues during the operation.",
  ui_story_5087_50871000_75_dialog_content = "... He's my most trusted companion, and he'll be your guide in the Winter Palace.",
  ui_story_5087_50871101_1_dialog_content = "... Shaya went on ahead of us and sneaked into the Winter Palace. She mentioned something about a secret passageway that only she could enter.",
  ui_story_5087_50871101_2_dialog_content = "Hahaha! She's in the form of a child right now.",
  ui_story_5087_50871101_3_dialog_content = "?",
  ui_story_5087_50871101_4_dialog_content = "Now, it's your turn. Security is always tight at the entrance...",
  ui_story_5087_50871101_5_dialog_content = "But you're always going in and out of the Winter Palace, so it isn't a problem, right?",
  ui_story_5087_50871101_6_dialog_content = "...",
  ui_story_5087_50871101_7_dialog_content = "I-I think so!",
  ui_story_5087_50871101_8_dialog_content = "Halt.",
  ui_story_5087_50871101_9_dialog_content = "Hello, I'm Nikinis, and this is Nepolis. We have business in the Winter Palace—",
  ui_story_5087_50871101_10_dialog_content = "Entry is prohibited to the public until the mirror thief is captured.",
  ui_story_5087_50871101_11_dialog_content = "(... What?)",
  ui_story_5087_50871101_12_dialog_content = "We're not just anyone. We found the stolen Northland Mirror.",
  ui_story_5087_50871101_13_dialog_content = "We're under Her Majesty's orders to track down the thief, and we just discovered a clue that requires cross-checking at the palace's library.",
  ui_story_5087_50871101_14_dialog_content = "Could you let us through? We're all serving Her Majesty here.",
  ui_story_5087_50871101_15_dialog_content = "Oh... Hmm...",
  ui_story_5087_50871101_16_dialog_content = "Your help will be rewarded, of course. I'll visit with the fine tea bestowed by Her Majesty, and we can enjoy it together!",
  ui_story_5087_50871101_17_dialog_content = "Really? Ahem... On second thought, you're closely related to the theft and should be allowed entry.",
  ui_story_5087_50871101_18_dialog_content = "You may pass.",
  ui_story_5087_50871101_19_dialog_content = "(That worked!)",
  ui_story_5087_50871101_20_dialog_content = "... Take a right up ahead, continue straight, then go down the stairs.",
  ui_story_5087_50871101_21_dialog_content = "Keep your eyes open. Zarya often sits by the bay window there to enjoy the view. Don't let her catch you.",
  ui_story_5087_50871101_22_dialog_content = "Zarya? Who's that? Well, I've looked, and there's no one there.",
  ui_story_5087_50871101_23_dialog_content = "Does Zarya not appear in the other world yet? Oh, I've said too much... Ah! Get down! Novio's bunnies are definitely hiding in that courtyard outside!",
  ui_story_5087_50871101_24_dialog_content = "Keep an eye out while descending the stairs too. I almost got sent six feet under by a sheet of ice Noah left behind...",
  ui_story_5087_50871101_25_dialog_content = "Seriously, who are you? You're acting so secretively, yet you possess extensive knowledge about the structure and personnel of the Winter Palace... Are you sure you're not a spy?",
  ui_story_5087_50871101_26_dialog_content = "Trust me, I'm a good person!",
  ui_story_5087_50871101_27_dialog_content = "... Everything will be revealed once the mirror is repaired.",
  ui_story_5087_50871101_28_dialog_content = "... Humph.",
  ui_story_5087_50871101_29_dialog_content = "Well, we've already come this far, so let's just put our trust in him and Shaya.",
  ui_story_5087_50871101_30_dialog_content = "Speaking of which, we wouldn't have made it here without you. If I were alone, I wouldn't have even made it inside.",
  ui_story_5087_50871101_31_dialog_content = "You're concerned about my feelings again, aren't you?",
  ui_story_5087_50871101_32_dialog_content = "No, I'm not!",
  ui_story_5087_50871101_33_dialog_content = "I can sense your feelings, remember?",
  ui_story_5087_50871101_34_dialog_content = "...",
  ui_story_5087_50871101_35_dialog_content = "Nikinis, remember the memory disorder you mentioned? Are you sure it isn't an aftereffect of your illness?",
  ui_story_5087_50871101_36_dialog_content = "Well... I don't know, to be honest, but something tells me there's more to it than meets the eye.",
  ui_story_5087_50871101_37_dialog_content = "Well then... Let's solve all the mysteries. No matter what you do, I'll always be there by your side.",
  ui_story_5087_50871101_38_dialog_content = "... I'm sorry for always dragging you into things...",
  ui_story_5087_50871101_39_dialog_content = "Not at all. I came to this decision after much deliberation.",
  ui_story_5087_50871101_40_dialog_content = "I did a lot of thinking on our way to the Winter Palace. I thought about the past and recent events...",
  ui_story_5087_50871101_41_dialog_content = "I realized that maybe we never were that similar, to begin with.",
  ui_story_5087_50871101_42_dialog_content = "!",
  ui_story_5087_50871101_43_dialog_content = "I prefer a lively atmosphere, yet you're fond of peace and quiet. I like small animals, but you prefer reading...",
  ui_story_5087_50871101_44_dialog_content = "I can make the royal guards move aside for us, but you can't do the same.",
  ui_story_5087_50871101_45_dialog_content = "Huh? I-I'll pick up everything you show me...",
  ui_story_5087_50871101_46_dialog_content = "Hehe... It's alright. It feels quite nice to know there are things that only I can achieve.",
  ui_story_5087_50871101_47_dialog_content = "I'm sure we'll get into more arguments in the future, because we're not the same after all. It's impossible for us to always be on the same page.",
  ui_story_5087_50871101_48_dialog_content = "But it's no big deal, not even if the connection we share vanishes one day.",
  ui_story_5087_50871101_49_dialog_content = "As long as I have my mouth to seek your thoughts and a pair of legs to approach you...",
  ui_story_5087_50871101_50_dialog_content = "Our hearts will never be apart.",
  ui_story_5087_50871101_51_dialog_content = "Nepolis! Oh... I'm so happy to know you feel that way...",
  ui_story_5087_50871101_52_dialog_content = "You're the best! I'll never leave your side! Boo-hoo...",
  ui_story_5087_50871101_53_dialog_content = "Hey! Act your age! We're in the Winter Palace...",
  ui_story_5087_50871101_54_dialog_content = "A-Actually, I just had a similar conversation with Shaya... Wait a minute! Did you overhear our conversation?",
  ui_story_5087_50871101_55_dialog_content = "What conversation?",
  ui_story_5087_50871101_56_dialog_content = "Sorry to interrupt, but I sense something powerful pressing down on me... The Northland Mirror is close by.",
  ui_story_5087_50871101_57_dialog_content = "Danger may be lurking ahead, and I might be unable to give you further guidance at any moment—",
  ui_story_5087_50871101_58_dialog_content = "... It's alright.",
  ui_story_5087_50871101_59_dialog_content = "So, this is Winter Palace's treasure vault—the Room of Relics.",
  ui_story_5087_50871101_60_dialog_content = "Huh? Have you been here before?",
  ui_story_5087_50871101_61_dialog_content = "My sister and I used to play hide-and-seek here when we were little. Do you still remember the time we were receiving treatment in the Winter Palace, Nepolis?",
  ui_story_5087_50871101_62_dialog_content = "...",
  ui_story_5087_50871101_63_dialog_content = "Nepolis?",
  ui_story_5087_50871101_64_dialog_content = "They're... coming.",
  ui_story_5087_50871101_65_dialog_content = "Graah!",
  ui_story_5087_50871102_1_dialog_content = "Huff... Huff... These are some strong monsters. What are they doing in the Winter Palace?",
  ui_story_5087_50871102_2_dialog_content = "We'll figure it out later. Get into the Room of Relics! Hurry!",
  ui_story_5087_50871102_3_dialog_content = "The Northland Mirror! I knew I'd find you here...",
  ui_story_5087_50871102_4_dialog_content = "<color=#e8d9bb>The Northland Mirror is visibly damaged, with cracks and gaps all over it.</color>",
  ui_story_5087_50871102_5_dialog_content = "<color=#e8d9bb>Yet it still radiates a soft and gentle glow while countless shadows flicker on the mirror's cracked surface.</color>",
  ui_story_5087_50871102_6_dialog_content = "(Those figures give me such a familiar feeling...)",
  ui_story_5087_50871102_7_dialog_content = "Th-That mirror! Are you Lady Nikinis?",
  ui_story_5087_50871102_8_dialog_content = "Calm down. I am Nikinis, and I'm here on Queen Bethlehem's orders.",
  ui_story_5087_50871102_9_dialog_content = "I suspect ancient relics are the source of the series of strange events you've recently encountered.",
  ui_story_5087_50871102_10_dialog_content = "As it's a matter of the utmost importance, I ask that you tell me every detail.",
  ui_story_5087_50871102_11_dialog_content = "Sure!",
  ui_story_5087_50871102_12_dialog_content = "Graaah!",
  ui_story_5087_50871102_13_dialog_content = "Vile monster... I-I'll take you down!",
  ui_story_5087_50871102_14_dialog_content = "Monster, leave.",
  ui_story_5087_50871102_15_dialog_content = "Graaah...",
  ui_story_5087_50871102_16_dialog_content = "Lady Nikinis! Th-Thank you for saving me!",
  ui_story_5087_50871102_17_dialog_content = "Your life is a pure and precious thing. Next time, call out my name before risking your life in battle.",
  ui_story_5087_50871102_18_dialog_content = "I sneaked out of the celebration feast again... Everyone must think I'm arrogant and annoying.",
  ui_story_5087_50871102_19_dialog_content = "But I really have no idea how to act there. All of them seem so happy, and only I...",
  ui_story_5087_50871102_20_dialog_content = "Lady Nikinis!",
  ui_story_5087_50871102_21_dialog_content = "You're from back then—",
  ui_story_5087_50871102_22_dialog_content = "I saw you sneak off, b-but I didn't get to give this to you yet!",
  ui_story_5087_50871102_23_dialog_content = "A bouquet of narcissuses and lilies...",
  ui_story_5087_50871102_24_dialog_content = "I heard they are your favorite flowers.",
  ui_story_5087_50871102_25_dialog_content = "Lady Nikinis, I can't thank you enough for always fighting by our side and protecting us!",
  ui_story_5087_50871102_26_dialog_content = "(Was that... my memory just now?)",
  ui_story_5087_50871102_27_dialog_content = "(Was I ever that awe-inspiring and calm? Did I take part in that many important events?)",
  ui_story_5087_50871102_28_dialog_content = "<color=#e8d9bb>As if drawn by her recovered memories, Nikinis inches forward toward the Northland Mirror and places her palm over it—</color>",
  ui_story_5087_50871102_29_dialog_content = "It's whole again! ... You really have a special connection with it, Nikinis.",
  ui_story_5087_50871102_30_dialog_content = "Umm...",
  ui_story_5087_50871102_31_dialog_content = "This is great. Now, only the final step remains!",
  ui_story_5087_50871102_32_dialog_content = "The final step? Didn't you say that everything will be revealed once the mirror is repaired?",
  ui_story_5087_50871102_33_dialog_content = "Nikinis, you should have managed to retrieve a part of your memories while repairing the mirror.",
  ui_story_5087_50871102_34_dialog_content = "Now... All that's left is to <color=#FFB400>pass through the mirror</color>!",
  ui_story_5087_50871102_35_dialog_content = "What? Pass through to the other world?",
  ui_story_5087_50871102_36_dialog_content = "Exactly. It is where the real Queen Bethlehem resides. Your remaining memories and the answers you seek are also beyond the mirror!",
  ui_story_5087_50871102_37_dialog_content = "I-I don't know...",
  ui_story_5087_50871102_38_dialog_content = "Do it, Nikinis.",
  ui_story_5087_50871102_39_dialog_content = "Huh? You want me to enter the mirror?",
  ui_story_5087_50871102_40_dialog_content = "That's right. We've already come so far. We can't just turn around and head home, right?",
  ui_story_5087_50871102_41_dialog_content = "You must retrieve your memories, figure everything out, and come back to tell me every single detail.",
  ui_story_5087_50871102_42_dialog_content = "If that mirror dares to stop you, I won't rest until I bring you back, and we'll show it who's the boss!",
  ui_story_5087_50871102_43_dialog_content = "So, just do it. It's a promise.",
  ui_story_5087_50871102_44_dialog_content = "Nepolis...",
  ui_story_5087_50871102_45_dialog_content = "...",
  ui_story_5087_50871102_46_dialog_content = "Come on, Nikinis.",
  ui_story_5087_50871102_47_dialog_content = "I-I'll be going then, Nepolis!",
  ui_story_5087_50871102_48_dialog_content = "Okay.",
  ui_story_5087_50871102_49_dialog_content = "<color=#e8d9bb>The mirror glows brighter as if it's welcoming Nikinis, and she finally takes that step—</color>",
  ui_story_5087_50871102_50_dialog_content = "<color=#e8d9bb>Fizz.</color>",
  ui_story_5087_50871102_51_dialog_content = "Uh... Urgh! Don't even... think about it!",
  ui_story_5087_50871102_52_dialog_content = "What's wrong, Nepolis?",
  ui_story_5087_50871102_53_dialog_content = "I'm... fine... Hurry... Urghhhh!",
  ui_story_5087_50871102_54_dialog_content = "...",
  ui_story_5087_50871102_55_dialog_content = "Nepolis! Nepolis! Are you okay?",
  ui_story_5087_50871102_56_dialog_content = "Nikinis! Stay away from your sister! I'm afraid she—",
  ui_story_5087_50871102_57_dialog_content = "... Nikinis.",
  ui_story_5087_50871102_58_dialog_content = "I'm right here! How do you feel? Are you hurt anywhere?",
  ui_story_5087_50871102_59_dialog_content = "The other side of the mirror... is extremely dangerous.",
  ui_story_5087_50871102_60_dialog_content = "Huh?",
  ui_story_5087_50871102_61_dialog_content = "I can't let you go to such a dangerous place. Just stay by my side, okay?",
  ui_story_5087_50871102_62_dialog_content = "B-But... You just said...",
  ui_story_5087_50871102_63_dialog_content = "I'm afraid... I'm afraid of losing you... Once you go through the mirror, I'll never see you again.",
  ui_story_5087_50871102_64_dialog_content = "All I need is you, and I think you too feel the same way, right?",
  ui_story_5087_50871102_65_dialog_content = "You would be so lonely without me... You wouldn't even be able to face the smiles of the people at a party.",
  ui_story_5087_50871102_66_dialog_content = "!",
  ui_story_5087_50871102_67_dialog_content = "The happier others are, the more painful it gets for you. Because deep down inside, you know that your happiness is never coming back...",
  ui_story_5087_50871102_68_dialog_content = "Stay with me, my sister... My Nikinis—",
  ui_story_5087_50871102_69_dialog_content = "Nikinis, don't let her deceive you. That isn't your sister anymore!",
  ui_story_5087_50871102_70_dialog_content = "You must pass through the mirror! You're within the <color=#FFB400>mirror world</color> created by the Northland Mirror! And this side—",
  ui_story_5087_50871102_71_dialog_content = "This is where <color=#FFB400>reality</color> truly lies!",
  ui_story_5087_50871102_72_dialog_content = "!",
  ui_story_5087_50871102_73_dialog_content = "Haven't you noticed? Nothing in this world seems right!",
  ui_story_5087_50871102_74_dialog_content = "Something's not right... Yes, I don't remember my parents ever working in the Winter Palace...",
  ui_story_5087_50871102_75_dialog_content = "Because it was fabricated by the Northland Mirror!",
  ui_story_5087_50871102_76_dialog_content = "The Winter Palace is too clean...",
  ui_story_5087_50871102_77_dialog_content = "Because there are no shadows! Everything here is a shadowless illusion created by the mirror! Even the queen is an illusion!",
  ui_story_5087_50871102_78_dialog_content = "It's true! The candles and furniture don't have shadows, but I do! And Nepolis...",
  ui_story_5087_50871102_79_dialog_content = "... Wait! You're wrong! Nepolis has a shadow! She's real!",
  ui_story_5087_50871102_80_dialog_content = "... Is Shaya still not here yet? She'll explain everything to you! At this point, I suppose I can tell you the truth. Shaya is Beth—",
  ui_story_5087_50871102_81_dialog_content = "She isn't coming.",
  ui_story_5087_50871102_82_dialog_content = "You're—",
  ui_story_5087_50871102_83_dialog_content = "<color=#e8d9bb>Nikinis instinctively glances at the queen's feet. There's nothing there, nor is there anything by the feet of the royal guards.</color>",
  ui_story_5087_50871102_84_dialog_content = "<color=#e8d9bb>Nothing! There's nothing there! None of them have a shadow!</color>",
  ui_story_5087_50871102_85_dialog_content = "<color=#e8d9bb>The \"queen\" freezes the Northland Mirror with a flick of her palm, and with another flick, the mirror flies off and shatters into bits.</color>",
  ui_story_5087_50871102_86_dialog_content = "... So you are a fake!",
  ui_story_5087_50871102_87_dialog_content = "I'm not the only one. Show yourselves, everyone.",
  ui_story_5087_50871102_88_dialog_content = "Graaah!",
  ui_story_5087_50871102_89_dialog_content = "Don't even think about it! I won't let you hurt Nepolis—",
  ui_story_5087_50871102_90_dialog_content = "Nepolis? Heh, you verified my shadow, but you're not doing the same for her?",
  ui_story_5087_50871102_91_dialog_content = "No... She's different...",
  ui_story_5087_50871102_92_dialog_content = "Graah! Graaah!",
  ui_story_5087_50871102_93_dialog_content = "Why would I fabricate the lives of your parents? Because they only live in this world!",
  ui_story_5087_50871102_94_dialog_content = "Just like Nepolis.",
  ui_story_5087_50871102_95_dialog_content = "No... Stop it!",
  ui_story_5087_50871102_96_dialog_content = "... Gosh, we've known each other for so long. I thought you were smarter than this.",
  ui_story_5087_50871102_97_dialog_content = "Well, I'll capture you first, then slowly make you face reality.",
  ui_story_5087_50871102_98_dialog_content = "Get her! It doesn't matter if you're a little rough!",
  ui_story_5087_50871102_99_dialog_content = "Graaah!",
  ui_story_5087_50871102_100_dialog_content = "<color=#e8d9bb>Urgh! The heaviest hit doesn't land on Nikinis.</color>",
  ui_story_5087_50871102_101_dialog_content = "N-Nepolis?",
  ui_story_5087_50871102_102_dialog_content = "<color=#e8d9bb>Nikinis watches as something dark and indistinct flows out of Nepolis' wound—</color>",
  ui_story_5087_50871102_103_dialog_content = "<color=#e8d9bb>And then, she starts melting on the spot.</color>",
  ui_story_5087_50871102_104_dialog_content = "No... This isn't real... Nepolis... Nepolis!",
  ui_story_5087_50871102_105_dialog_content = "N-Nikinis...",
  ui_story_5087_50871102_106_dialog_content = "Nepolis... No! No... Please don't go—",
  ui_story_5087_50871102_107_dialog_content = "R-Run!",
  ui_story_5087_50871102_108_dialog_content = "!",
  ui_story_5087_50871102_109_dialog_content = "<color=#e8d9bb>Countless monsters rush forward and sweep away Nepolis' shadowy figure.</color>",
  ui_story_5087_50871102_110_dialog_content = "NO! Where have you gone, Nepolis?",
  ui_story_5087_50871102_111_dialog_content = "<color=#e8d9bb>Nikinis grabs frantically, but all that's left is a mere wisp of dark mist that dissipates in her grasp.</color>",
  ui_story_5087_50871102_112_dialog_content = "Nepolis... Nepolis...",
  ui_story_5087_50871102_113_dialog_content = "Graaaaaah!",
  ui_story_5087_50871102_114_dialog_content = "...",
  ui_story_5087_50871102_115_dialog_content = "It's all your fault! You monsters!",
  ui_story_5087_50871102_116_dialog_content = "Graah...",
  ui_story_5087_50871102_117_dialog_content = "You regained a portion of your power from reality?",
  ui_story_5087_50871102_118_dialog_content = "Nepolis, where are you? Please don't scare me like this... Oh, you've gone on ahead to open up a path for me, right? Sheesh, you should have told me...",
  ui_story_5087_50871102_119_dialog_content = "I'm on my way to you!",
  ui_story_5087_50871102_120_dialog_content = "Nepolis—",
  ui_story_5087_50871102_121_dialog_content = "Nepolis...",
  ui_story_5087_50871102_122_dialog_content = "Nepolis, where are you? I'm begging you! Please come back to me...",
  ui_story_5087_50871102_123_dialog_content = "<color=#e8d9bb>Without realizing it, Nikinis arrives at the cottage where she found the Northland Mirror with Nepolis.</color>",
  ui_story_5087_50871102_124_dialog_content = "Nepolis, did you come here to wait for me?",
  ui_story_5087_50871102_125_dialog_content = "<color=#e8d9bb>Amid the overwhelming fragrance of flowers, the pure white flowers made from Luminatics remain in full bloom within the cottage.</color>",
  ui_story_5087_50871102_126_dialog_content = "<color=#e8d9bb>But only white narcissuses remain. Every one of them is a white narcissus.</color>",
  ui_story_5087_50871102_127_dialog_content = "<color=#e8d9bb>All the lilies are gone, as if they were never there, to begin with.</color>",
  ui_story_5087_50871102_128_dialog_content = "N-Nepolis?",
  ui_story_5087_50871102_129_dialog_content = "\"Can you recall those beautiful white flowers? Two stems growing in harmony by the tranquil lake.\"",
  ui_story_5087_50871102_130_dialog_content = "No, no, no...",
  ui_story_5087_50871102_131_dialog_content = "\"Under the falling gray snow, the pristine lily was soon buried.\"",
  ui_story_5087_50871102_132_dialog_content = "\"Left alone in the world, the white narcissus wept quietly.\"",
  ui_story_5087_50871102_133_dialog_content = "... Waaaaaaaaaaaaaaaaaaaah!",
  ui_story_5087_50871200_1_dialog_content = "How strange.",
  ui_story_5087_50871200_2_dialog_content = "Mom and dad said she's gone, but Nepolis has always been by my side.",
  ui_story_5087_50871200_3_dialog_content = "<color=#e8d9bb>Buzz... Flies land on some red meat that is gradually losing its shape.</color>",
  ui_story_5087_50871200_4_dialog_content = "That smell... Ah! Is that the apple stew from last week? What's it doing there, Nikinis?",
  ui_story_5087_50871200_5_dialog_content = "Even if you don't want to eat it, at least throw away the leftovers! Just look at that...",
  ui_story_5087_50871200_6_dialog_content = "But... That's Nepolis' share.",
  ui_story_5087_50871200_7_dialog_content = "!",
  ui_story_5087_50871200_8_dialog_content = "How strange. Why won't Nepolis eat it? Apple stew is her favorite.",
  ui_story_5087_50871200_9_dialog_content = "I know! She must be having a poor appetite lately! She even talks less now... Is it an aftereffect of her illness?",
  ui_story_5087_50871200_10_dialog_content = "Found you! Now, who's next?",
  ui_story_5087_50871200_11_dialog_content = "Hey! Let us join you guys!",
  ui_story_5087_50871200_12_dialog_content = "Huh? But you're all alone.",
  ui_story_5087_50871200_13_dialog_content = "What do you mean? My sister's right by my side! She's been talking less lately, but I know she wants to play with everyone!",
  ui_story_5087_50871200_14_dialog_content = "Our Luminatics is linked, so I know everything she's thinking.",
  ui_story_5087_50871200_15_dialog_content = "... She's crazy.",
  ui_story_5087_50871200_16_dialog_content = "Nikinis is crazy! She's gone mad!",
  ui_story_5087_50871200_17_dialog_content = "You're crazy! You're mad! My sister is just sick, and that weakened her Luminatics! She's always there! I can see her!",
  ui_story_5087_50871200_18_dialog_content = "Your Majesty, I'm begging you. Please help Nikinis! Since Nepolis... you know, she's been like this since then...",
  ui_story_5087_50871200_19_dialog_content = "The doctors are stumped! You're our last hope! I'm begging you, Your Majesty!",
  ui_story_5087_50871200_20_dialog_content = "... Your twin daughters' situation is an extremely rare case.",
  ui_story_5087_50871200_21_dialog_content = "I do have an idea, but it's too dangerous. Let me give it more thought.",
  ui_story_5087_50871200_22_dialog_content = "Your name is Nikinis? It's a beautiful name. Since your sister, Nepolis, isn't fond of talking, could you introduce her to me?",
  ui_story_5087_50871200_23_dialog_content = "Did you just... ask about my sister? Thank goodness! Someone finally believes me!",
  ui_story_5087_50871200_24_dialog_content = "But could you treat her first? She's sick, and she still hasn't fully recovered until now...",
  ui_story_5087_50871200_25_dialog_content = "Our souls are one, so treating me alone won't work... I'll be fine once she's fine!",
  ui_story_5087_50871200_26_dialog_content = "...",
  ui_story_5087_50871200_27_dialog_content = "Nepolis, Nepolis! Her Majesty will definitely be able to cure you! This is great news!",
  ui_story_5087_50871200_28_dialog_content = "Yes... I'm overjoyed too...",
  ui_story_5087_50871200_29_dialog_content = "So, how about a game of hide-and-seek? It's not every day that we get to spend the night in the Winter Palace. Let's have some fun!",
  ui_story_5087_50871200_30_dialog_content = "This place feels really mysterious... Nepolis, do you sense it too?",
  ui_story_5087_50871200_31_dialog_content = "...",
  ui_story_5087_50871200_32_dialog_content = "Little Aurorian... Little Aurorian over there...",
  ui_story_5087_50871200_33_dialog_content = "Huh? Who's there? Who are you talking to? Is it me? Or my sister?",
  ui_story_5087_50871200_34_dialog_content = "Only you can see your sister and sense her soul. It's lonely, isn't it, little Aurorian...",
  ui_story_5087_50871200_35_dialog_content = "!",
  ui_story_5087_50871200_36_dialog_content = "I... can help you. Come closer...",
  ui_story_5087_50871200_37_dialog_content = "... A mirror? How is a mirror supposed to help me?",
  ui_story_5087_50871200_38_dialog_content = "Little Aurorian, you know nothing about the mirror's power.",
  ui_story_5087_50871200_39_dialog_content = "I can restore your sister to her former glory. Everyone will be able to see and sense her—",
  ui_story_5087_50871200_40_dialog_content = "But you must make a pact with me.",
  ui_story_5087_50871200_41_dialog_content = "I-Is that true? She'll play with me, joke with me, and fight with me, just like she used to?",
  ui_story_5087_50871200_42_dialog_content = "What must I do?",
  ui_story_5087_50871200_43_dialog_content = "Give me your... Lumina.",
  ui_story_5087_50871200_44_dialog_content = "My Lumina? Like this?",
  ui_story_5087_50871200_45_dialog_content = "<color=#e8d9bb>Her young palm covers the mirror—</color>",
  ui_story_5087_50871200_46_dialog_content = "The relic has been awakened! It's absorbing Lumina... Notify Her Majesty immediately!",
  ui_story_5087_50871200_47_dialog_content = "That child, Nikinis... She's still unconscious. The Northland Mirror took too much Lumina from her.",
  ui_story_5087_50871200_48_dialog_content = "Will she ever wake up again?",
  ui_story_5087_50871200_49_dialog_content = "The Northland Mirror has chosen her as its host. Her chances of survival are slim.",
  ui_story_5087_50871200_50_dialog_content = "... Unless I seal her body with the Northland Mirror.",
  ui_story_5087_50871200_51_dialog_content = "If she can adapt to the relic and regain consciousness on her own, she'll survive. Otherwise...",
  ui_story_5087_50871200_52_dialog_content = "I guess that's the only solution...",
  ui_story_5087_50871200_53_dialog_content = "*sighs* This is the exact situation you were trying to avoid by not treating her with the Northland Mirror.",
  ui_story_5087_50871200_54_dialog_content = "We could have never known the Northland Mirror would entice her... Is she that compatible with it?",
  ui_story_5087_50871200_55_dialog_content = "You can't call that \"treatment.\" It's just utilizing the Northland Mirror's power in the mental realm to—",
  ui_story_5087_50871200_56_dialog_content = "Forcibly remove the remnants of Luminatics left by her late sister.",
  ui_story_5087_50871200_57_dialog_content = "Luminatics of one sister remaining within the other sister is quite wondrous indeed.",
  ui_story_5087_50871200_58_dialog_content = "Nikinis and Nepolis are special. Their connection is so close that it's almost like a single soul split into two bodies.",
  ui_story_5087_50871200_59_dialog_content = "That's why Nikinis' treatment must be conducted with extreme caution. If her sister's remnants are forcibly removed—",
  ui_story_5087_50871200_60_dialog_content = "While she certainly will not \"see\" her sister again, the time they spent together, the memories they shared, the perceptions they formed together...",
  ui_story_5087_50871200_61_dialog_content = "Everything will be thrown into disorder or even vanish.",
  ui_story_5087_50871200_62_dialog_content = "It will be no different than stripping away half of her.",
  ui_story_5087_50871200_63_dialog_content = "Indeed. That risk is impossible to eliminate, not even with the Northland Mirror's help.",
  ui_story_5087_50871200_64_dialog_content = "Twin sisters connected in both mind and soul, but the elder sister got sick...",
  ui_story_5087_50871200_65_dialog_content = "And death separated them... Why does fate always play such tricks on us all?",
  ui_story_5087_50871200_66_dialog_content = "... But are they truly separated?",
  ui_story_5087_50871200_67_dialog_content = "Novio, do you believe that... an Aurorian's soul exists within Luminatics?",
  ui_story_5087_50871300_1_dialog_content = "(I remember now, all of it.)",
  ui_story_5087_50871300_2_dialog_content = "(Nepolis passed away a long time ago, and Queen Bethlehem sealed me in the frozen cave to save my life.)",
  ui_story_5087_50871300_3_dialog_content = "(Both mom and dad passed away during this time.)",
  ui_story_5087_50871300_4_dialog_content = "(I couldn't even remember living with my parents after regaining consciousness...)",
  ui_story_5087_50871300_5_dialog_content = "<color=#e8d9bb>Upon opening her eyes in the frozen cave, the Aurorian known as Nikinis had nothing left.</color>",
  ui_story_5087_50871300_6_dialog_content = "<color=#e8d9bb>No home, hometown, or memories. She was alone in the world with only her frail and incomplete self.</color>",
  ui_story_5087_50871300_7_dialog_content = "<color=#e8d9bb>Besides the soft glow of the magic mirror by her side, the only other thing to greet her was—</color>",
  ui_story_5087_50871300_8_dialog_content = "<color=#e8d9bb>A smiling mirror image of herself, walking out from amid the fully bloomed lilies reflected on the mirror's surface.</color>",
  ui_story_5087_50871300_9_dialog_content = "\"What are you staring at? Don't you recognize your own sister?\"",
  ui_story_5087_50871300_10_dialog_content = "\"My Nikinis... My other half...\"",
  ui_story_5087_50871300_11_dialog_content = "(All of this... This is my reality...)",
  ui_story_5087_50871300_12_dialog_content = "(A more cruel and terrible reality than the mirror world.)",
  ui_story_5087_50871300_13_dialog_content = "Then why don't you stay in the mirror?",
  ui_story_5087_50871300_14_dialog_content = "...",
  ui_story_5087_50871300_15_dialog_content = "You again... You still have the nerve to speak to me so shamelessly...",
  ui_story_5087_50871300_16_dialog_content = "It's all your fault!",
  ui_story_5087_50871300_17_dialog_content = "Don't be so judgmental... All I did was fulfill your wish.",
  ui_story_5087_50871300_18_dialog_content = "You wanted to enjoy life with your sister, and I gave you that. You wanted to fight by her side, and I gave you that too.",
  ui_story_5087_50871300_19_dialog_content = "Even the memories of reality that you sought to recover, I gave them to you as well—even if that wouldn't benefit me in any way.",
  ui_story_5087_50871300_20_dialog_content = "Oh, I wish you would show some gratitude. My host and contractor...",
  ui_story_5087_50871300_21_dialog_content = "I retrieved my own memories! Don't even think about taking credit for that!",
  ui_story_5087_50871300_22_dialog_content = "How did it feel to retrieve those memories? Did you enjoy it?",
  ui_story_5087_50871300_23_dialog_content = "...",
  ui_story_5087_50871300_24_dialog_content = "It wasn't fun, was it? The darkness and boredom of real life is something that I, the creator of illusions, know better than anyone.",
  ui_story_5087_50871300_25_dialog_content = "So, stay within the mirror.",
  ui_story_5087_50871300_26_dialog_content = "I can fulfill your every desire.",
  ui_story_5087_50871300_27_dialog_content = "Anything that can be reflected by the mirror is a gift from me to you.",
  ui_story_5087_50871300_28_dialog_content = "All it takes is a thought for you to become the ruler of the mirror world! The entire world will be at your feet!",
  ui_story_5087_50871300_29_dialog_content = "Or your greed isn't that great? Maybe what you desire is merely—",
  ui_story_5087_50871300_30_dialog_content = "Nikinis, I don't want to lose you again...",
  ui_story_5087_50871300_31_dialog_content = "Nepolis!",
  ui_story_5087_50871300_32_dialog_content = "Stay with me. You'll fulfill this tiny wish of mine, won't you?",
  ui_story_5087_50871300_33_dialog_content = "I...",
  ui_story_5087_50871300_34_dialog_content = "If you stay within the mirror, I can take your place <color=#FFB400>in reality</color>.",
  ui_story_5087_50871300_35_dialog_content = "Lilies will once again bloom in Northland... and even throughout the lands of Astra.",
  ui_story_5087_50871300_36_dialog_content = "... Really? Is that your wish?",
  ui_story_5087_50871300_37_dialog_content = "Yes.",
  ui_story_5087_50871300_38_dialog_content = "Well, in that case...",
  ui_story_5087_50871300_39_dialog_content = "I'll do it.",
  ui_story_5087_50871400_1_dialog_content = "I cannot believe this forest, snowy plains, frost, and everything is part of the mirror's illusion.",
  ui_story_5087_50871400_2_dialog_content = "It's no different from reality!",
  ui_story_5087_50871400_3_dialog_content = "Nikinis... Nikinis...",
  ui_story_5087_50871400_4_dialog_content = "The mirror world isn't that bad, or rather, there is nothing bad about it at all.",
  ui_story_5087_50871400_5_dialog_content = "Nikinis—",
  ui_story_5087_50871400_6_dialog_content = "Nepolis and my parents, they're all with me again...",
  ui_story_5087_50871400_7_dialog_content = "Nikinis!",
  ui_story_5087_50871400_8_dialog_content = "!",
  ui_story_5087_50871400_9_dialog_content = "<color=#e8d9bb>Heavy snowfall continued for several days, and the ice and snow throughout Northland grew increasingly crystalline. An ice crystal flutters with the wind and lands on Nikinis' palm.</color>",
  ui_story_5087_50871400_10_dialog_content = "<color=#e8d9bb>A familiar figure appears on the surface of the ice crystal.</color>",
  ui_story_5087_50871400_11_dialog_content = "The one in the mirror!",
  ui_story_5087_50871400_12_dialog_content = "No... I remember now. You're... PlayerName.",
  ui_story_5087_50871400_13_dialog_content = "You found this place... Did you go to all this trouble just to bring me back to reality?",
  ui_story_5087_50871400_14_dialog_content = "You remember everything? What a relief! Now listen, we must—",
  ui_story_5087_50871400_15_dialog_content = "... That's enough.",
  ui_story_5087_50871400_16_dialog_content = "Huh?",
  ui_story_5087_50871400_17_dialog_content = "I appreciate what you've done. During my time living in reality, I never expected someone would go to such lengths for me.",
  ui_story_5087_50871400_18_dialog_content = "But it's all right now. Get some rest. You don't have to waste time searching for me anymore.",
  ui_story_5087_50871400_19_dialog_content = "I intend to stay within the mirror.",
  ui_story_5087_50871400_20_dialog_content = "... Is it because of your sister?",
  ui_story_5087_50871400_21_dialog_content = "My \"sister\"... Indeed.",
  ui_story_5087_50871400_22_dialog_content = "Though she's merely an illusion the Northland Mirror created by extracting the remnants of her Luminatics from within me...",
  ui_story_5087_50871400_23_dialog_content = "She's still the same sister I knew.",
  ui_story_5087_50871400_24_dialog_content = "She wishes to live in reality again, and the lilies wish to bloom all over Northland...",
  ui_story_5087_50871400_25_dialog_content = "How could I refuse her only wish?",
  ui_story_5087_50871400_26_dialog_content = "Is that really what Nepolis wants? It's likely the magic mirror is making use of her image again so that you'll stay!",
  ui_story_5087_50871400_27_dialog_content = "Just like it did in the Room of Relics! It wants you to stay in the mirror so that it can gain full control of your body—",
  ui_story_5087_50871400_28_dialog_content = "That still won't change my decision.",
  ui_story_5087_50871400_29_dialog_content = "?",
  ui_story_5087_50871400_30_dialog_content = "If Nepolis' consciousness remains, and she wishes to return to reality with the mirror's help...",
  ui_story_5087_50871400_31_dialog_content = "Then I cannot go against her wishes and snuff out her hope to live.",
  ui_story_5087_50871400_32_dialog_content = "If Nepolis has been devoured by the mirror, and only an illusion of her remains...",
  ui_story_5087_50871400_33_dialog_content = "It proves the Northland Mirror has completely taken over half of my soul.",
  ui_story_5087_50871400_34_dialog_content = "If I return to reality in that state, even I cannot predict what kind of terrible things I may be manipulated into doing.",
  ui_story_5087_50871400_35_dialog_content = "... It's likely that I would even hurt you.",
  ui_story_5087_50871400_36_dialog_content = "Now's not the time to worry about me!",
  ui_story_5087_50871400_37_dialog_content = "I have no right to ignore your well-being when you refuse to abandon me!",
  ui_story_5087_50871400_38_dialog_content = "Listen to me! I don't think Nepolis—",
  ui_story_5087_50871400_39_dialog_content = "PlayerName, tell Her Majesty to reseal me.",
  ui_story_5087_50871400_40_dialog_content = "It's the only way I can protect both Nepolis and you—",
  ui_story_5087_50871400_41_dialog_content = "NO! Just listen to me!",
  ui_story_5087_50871400_42_dialog_content = "What...",
  ui_story_5087_50871400_43_dialog_content = "There's a third possibility!",
  ui_story_5087_50871400_44_dialog_content = "A third... possibility?",
  ui_story_5087_50871400_45_dialog_content = "According to you, Nepolis either willingly chose the Northland Mirror, or the mirror devoured her a long time ago...",
  ui_story_5087_50871400_46_dialog_content = "But those aren't the only possibilities!",
  ui_story_5087_50871400_47_dialog_content = "What if her consciousness remains, and... she is still resisting the mirror?",
  ui_story_5087_50871400_48_dialog_content = "She had fallen to the mirror's control in the Room of Relics...",
  ui_story_5087_50871400_49_dialog_content = "... But didn't she regain her consciousness at the last moment and save you?",
  ui_story_5087_50871400_50_dialog_content = "!",
  ui_story_5087_50871400_51_dialog_content = "N-Nikinis...",
  ui_story_5087_50871400_52_dialog_content = "R-Run!",
  ui_story_5087_50871400_53_dialog_content = "Seeing you escape the mirror's control and live a good life is what Nepolis <color=#FFB400>truly desires</color>!",
  ui_story_5087_50871400_54_dialog_content = "Nepolis... Her true desire? She doesn't want me to stay in the mirror? She doesn't want me to stay by her side?",
  ui_story_5087_50871400_55_dialog_content = "... Of course she wants to be with you.",
  ui_story_5087_50871400_56_dialog_content = "But she would prefer seeing you spread your wings, fly high, and become a free and independent soul!",
  ui_story_5087_50871400_57_dialog_content = "I refuse to strip you of your wings.",
  ui_story_5087_50871400_58_dialog_content = "Do it, Nikinis.",
  ui_story_5087_50871400_59_dialog_content = "You must retrieve your memories, figure everything out, and come back to tell me every single detail.",
  ui_story_5087_50871400_60_dialog_content = "So, just do it. It's a promise.",
  ui_story_5087_50871400_61_dialog_content = "Why... Nepolis? A-Are you really still by my side?",
  ui_story_5087_50871400_62_dialog_content = "Even after losing her physical form, she still remains and desires to protect you.",
  ui_story_5087_50871400_63_dialog_content = "Go back, Nikinis! Just return to reality. You can leave the mirror and Nepolis to Shaya.",
  ui_story_5087_50871400_64_dialog_content = "I'm sure she'll find a way!",
  ui_story_5087_50871400_65_dialog_content = "Shaya... Yellow roses and forgive-me-nots... Ah! Don't tell me—",
  ui_story_5087_50871400_66_dialog_content = "Oh, and there's another thing you've got wrong.",
  ui_story_5087_50871400_67_dialog_content = "I've never been the only one who would do everything in their power for you.",
  ui_story_5087_50871400_68_dialog_content = "Your Majesty, I've always wanted to present these flowers to you as they symbolize—",
  ui_story_5087_50871400_69_dialog_content = "A cherished friendship, right?",
  ui_story_5087_50871400_70_dialog_content = "You've been wandering the gardens for so many days that I started wondering when you would finally be willing to give those flowers to me.",
  ui_story_5087_50871400_71_dialog_content = "Shaya is the real Queen Bethlehem.",
  ui_story_5087_50871400_72_dialog_content = "She entered the mirror world to bring you back!",
  ui_story_5087_50871501_1_dialog_content = "Her Majesty has declared Nikinis an accomplice to the theft in the Winter Palace! She is currently on the run! Hiding or aiding her is a crime!",
  ui_story_5087_50871501_2_dialog_content = "The thieves will use mirrors to wreak havoc. Northlanders!",
  ui_story_5087_50871501_3_dialog_content = "Destroy all mirrors immediately! Anything that can reflect a person's image must be destroyed!",
  ui_story_5087_50871501_4_dialog_content = "Graah!",
  ui_story_5087_50871501_5_dialog_content = "Graah...",
  ui_story_5087_50871501_6_dialog_content = "What the situation is like, Nikinis? Urgh, these monsters just won't give up...",
  ui_story_5087_50871501_7_dialog_content = "It's not too bad. What's my next move?",
  ui_story_5087_50871501_8_dialog_content = "... Give me a moment to think. The Northland Mirror has noticed my intentions and is attempting to destroy all the exits...",
  ui_story_5087_50871501_9_dialog_content = "The order to destroy all mirrors?",
  ui_story_5087_50871501_10_dialog_content = "That's right. Mirrors are passageways to reality. The stability and connectivity of a passageway is proportional to the mirror's surface area and reflectance.",
  ui_story_5087_50871501_11_dialog_content = "This tiny ice crystal is able to facilitate communication between us at most. It's not enough to bring you back to reality.",
  ui_story_5087_50871501_12_dialog_content = "So I need a large and smooth mirror?",
  ui_story_5087_50871501_13_dialog_content = "Exactly. The Northland Mirror itself is the best passageway. Shaya entered this world through it and stole it...",
  ui_story_5087_50871501_14_dialog_content = "The plan was to secure our passageway before convincing you to return to reality.",
  ui_story_5087_50871501_15_dialog_content = "Unfortunately, the fake queen was a step ahead of us and commanded the monsters dwelling within the Northland Mirror to destroy it...",
  ui_story_5087_50871501_16_dialog_content = "... She destroyed the mirror? And she even put on an act to make my sister and I search for it!",
  ui_story_5087_50871501_17_dialog_content = "PlayerName, you know the Winter Palace like the back of your hand—",
  ui_story_5087_50871501_18_dialog_content = "Is there a way to sneak into the Room of Relics again and get to the Northland Mirror?",
  ui_story_5087_50871501_19_dialog_content = "I'm afraid the Room of Relics is probably the most heavily-guarded location in Northland...",
  ui_story_5087_50871501_20_dialog_content = "Then we should forget about the Northland Mirror and focus on finding another way.",
  ui_story_5087_50871501_21_dialog_content = "Now that the fake queen has ordered the destruction of all mirrors, securing another passageway won't be easy at all... But you are right! There's no other way!",
  ui_story_5087_50871501_22_dialog_content = "You're unexpectedly calm, Nikinis. It feels like I'm looking at your awe-inspiring and indomitable figure on the battlefield again.",
  ui_story_5087_50871501_23_dialog_content = "... Because Nepolis is gone.",
  ui_story_5087_50871501_24_dialog_content = "I had no one to rely on or spoil me back then.",
  ui_story_5087_50871501_25_dialog_content = "Nikinis...",
  ui_story_5087_50871501_26_dialog_content = "You chose to take the path without your sister.",
  ui_story_5087_50871501_27_dialog_content = "!",
  ui_story_5087_50871501_28_dialog_content = "<color=#e8d9bb>Snow drifts with the wind, like menacing soldiers whistling through the wind as they answer the call of the battle drums—</color>",
  ui_story_5087_50871501_29_dialog_content = "<color=#e8d9bb>Escorting the figure approaching on her feet and bowing before her frosty gaze.</color>",
  ui_story_5087_50871501_30_dialog_content = "It's the \"queen\"! Among all the Northland Mirror's reflections...",
  ui_story_5087_50871501_31_dialog_content = "... She's the strongest.",
  ui_story_5087_50871501_32_dialog_content = "Since you're aware of that, just surrender, Nikinis.",
  ui_story_5087_50871501_33_dialog_content = "A quiet and cozy life with your parents and sister. Just say the word and it's yours.",
  ui_story_5087_50871501_34_dialog_content = "... But I must lay down in the dark snow and forget my wings.",
  ui_story_5087_50871501_35_dialog_content = "Do you really want those partially destroyed wings?",
  ui_story_5087_50871501_36_dialog_content = "They will only bring you pain. Every fruitless flap of those wings is a reminder—",
  ui_story_5087_50871501_37_dialog_content = "It reminds me that Nepolis was once here.",
  ui_story_5087_50871501_38_dialog_content = "!",
  ui_story_5087_50871501_39_dialog_content = "It reminds me of the joy and freedom we shared while soaring together.",
  ui_story_5087_50871501_40_dialog_content = "Nepolis would be disappointed if I abandoned those memories.",
  ui_story_5087_50871501_41_dialog_content = "I will never let my sister down.",
  ui_story_5087_50871501_42_dialog_content = "... If that's your decision—",
  ui_story_5087_50871501_43_dialog_content = "Nikinis! Watch out!",
  ui_story_5087_50871501_44_dialog_content = "Urgh!",
  ui_story_5087_50871501_45_dialog_content = "<color=#e8d9bb>The snow sweeps up a shadow that seems to almost freeze the world around it.</color>",
  ui_story_5087_50871501_46_dialog_content = "<color=#e8d9bb>The strength of the \"queen\" is far beyond most Aurorians.</color>",
  ui_story_5087_50871501_47_dialog_content = "<color=#e8d9bb>Nikinis gives it everything she's got, yet she's barely able to defend herself and the tiny ice crystal in her grasp.</color>",
  ui_story_5087_50871501_48_dialog_content = "Is that fragile ice crystal your last mirror? What a pity.",
  ui_story_5087_50871501_49_dialog_content = "Every snowflake in Northland... is a subject of mine!",
  ui_story_5087_50871501_50_dialog_content = "... I won't... let you... take my mirror! Aaaah!",
  ui_story_5087_50871501_51_dialog_content = "Mirror... Wait a minute! We still have one more mirror! How could I have forgotten?",
  ui_story_5087_50871501_52_dialog_content = "Well, it's not too late.",
  ui_story_5087_50871501_53_dialog_content = "!",
  ui_story_5087_50871501_54_dialog_content = "Shaya? No, you're...",
  ui_story_5087_50871501_55_dialog_content = "Both of you did well, PlayerName and Nikinis.",
  ui_story_5087_50871501_56_dialog_content = "And you... I believe a reckoning is in order.",
  ui_story_5087_50871501_57_dialog_content = "...",
  ui_story_5087_50871501_58_dialog_content = "Dance for me! Northland's snow!",
  ui_story_5087_50871502_1_dialog_content = "<color=#e8d9bb>Silvery snow shoots across the air majestically and stops the raging dark snow from approaching.</color>",
  ui_story_5087_50871502_2_dialog_content = "Get out of my way.",
  ui_story_5087_50871502_3_dialog_content = "Stop trying to be the hero when you're just a stray dog who has to sneak into the Winter Palace!",
  ui_story_5087_50871502_4_dialog_content = "You're not the queen here!",
  ui_story_5087_50871502_5_dialog_content = "... You know nothing about ruling.",
  ui_story_5087_50871502_6_dialog_content = "Northland's snow needs no sovereign. Nor do Northlanders who coexist with the snow require unnecessary shackles.",
  ui_story_5087_50871502_7_dialog_content = "The sole reason for the sovereign's existence is to inherit the power to protect Northland.",
  ui_story_5087_50871502_8_dialog_content = "I may be the queen, but I am first and foremost a warrior of Northland—",
  ui_story_5087_50871502_9_dialog_content = "You think I'll just let you lay your hands on my friends? Why don't you try getting through my blizzard first?",
  ui_story_5087_50871502_10_dialog_content = "Your Majesty...",
  ui_story_5087_50871502_11_dialog_content = "How ridiculous!",
  ui_story_5087_50871502_12_dialog_content = "No one is my match in the mirror world!",
  ui_story_5087_50871502_13_dialog_content = "Your Majesty, let me help you! Urgh! Oh no—",
  ui_story_5087_50871502_14_dialog_content = "<color=#e8d9bb>Silver gales and dark snow clash like behemoths that could overturn the world.</color>",
  ui_story_5087_50871502_15_dialog_content = "<color=#e8d9bb>In a moment of carelessness, the tiny ice crystal slips from Nikinis' grasp and is swept away by the storm.</color>",
  ui_story_5087_50871502_16_dialog_content = "PlayerName!",
  ui_story_5087_50871502_17_dialog_content = "Don't worry about me! Hurry to <color=#FFB400>Lake Mirror</color>!",
  ui_story_5087_50871502_18_dialog_content = "Lake Mirror... That's your home! And it's your... last passageway...",
  ui_story_5087_50871502_19_dialog_content = "It's Northland's biggest, brightest, and most stable mirror—as well as the one most familiar to you!",
  ui_story_5087_50871502_20_dialog_content = "<color=#e8d9bb>The ice crystal is swallowed by the storm, and the Caelestite's voice is heard no more.</color>",
  ui_story_5087_50871502_21_dialog_content = "<color=#e8d9bb>Only the whistle of the snowy gales remains around Nikinis.</color>",
  ui_story_5087_50871502_22_dialog_content = "<color=#e8d9bb>Those who would do everything in their power for her are still fighting for her at this very moment, and that's the evidence.</color>",
  ui_story_5087_50871502_23_dialog_content = "Thank you, Shaya... Queen Bethlehem...",
  ui_story_5087_50871502_24_dialog_content = "I won't let you down!",
  ui_story_5087_50871601_1_dialog_content = "<color=#e8d9bb>The world may change, and storms may rage, but Lake Mirror remains unchanged.</color>",
  ui_story_5087_50871601_2_dialog_content = "<color=#e8d9bb>It rests there quietly among the mountains, clear as a mirror, and the same as ever.</color>",
  ui_story_5087_50871601_3_dialog_content = "<color=#e8d9bb>It bestows a cooling breeze, peaceful air, and gentle floral fragrance to Nikinis' dashing figure.</color>",
  ui_story_5087_50871601_4_dialog_content = "<color=#e8d9bb>The faint yet rich fragrance of pure white flowers.</color>",
  ui_story_5087_50871601_5_dialog_content = "(The field of flowers by Lake Mirror... Just a few days ago, I was enjoying the view here with Nepolis...)",
  ui_story_5087_50871601_6_dialog_content = "<color=#e8d9bb>Nikinis gently strokes the white flowers. Narcissuses and lilies grow in harmony by the tranquil lake.</color>",
  ui_story_5087_50871601_7_dialog_content = "<color=#e8d9bb>A picturesque scene that never fails to make her heart palpitate. She never stops her attempt to discover the meaning of it.</color>",
  ui_story_5087_50871601_8_dialog_content = "Let's give it another try, PlayerName. I would rather not be condemned to a life of being adrift, arrogant, boring, and without memories...",
  ui_story_5087_50871601_9_dialog_content = "And not even knowing the reason for my unhappiness.",
  ui_story_5087_50871601_10_dialog_content = "I'm starting to remember things... Please help me with your psychic abilities again!",
  ui_story_5087_50871601_11_dialog_content = "All right... But don't push yourself. Let's stop if you feel any discomfort, okay?",
  ui_story_5087_50871601_12_dialog_content = "\"Can you recall...\"",
  ui_story_5087_50871601_13_dialog_content = "!",
  ui_story_5087_50871601_14_dialog_content = "<color=#e8d9bb>A cheery fire burns in the fireplace, its warm light creating dancing shadows within the small cottage.</color>",
  ui_story_5087_50871601_15_dialog_content = "<color=#e8d9bb>In the fire's glow, four figures can be seen: a husband and wife, as well as their twin daughters who look like mirror images of one another.</color>",
  ui_story_5087_50871601_16_dialog_content = "\"Can you recall those beautiful white flowers? A pair growing in harmony by the tranquil lake.\"",
  ui_story_5087_50871601_17_dialog_content = "...",
  ui_story_5087_50871601_18_dialog_content = "\"PlayerName, I remember now.\"",
  ui_story_5087_50871601_19_dialog_content = "\"It's just a short memory of our parents telling a story to us.\"",
  ui_story_5087_50871601_20_dialog_content = "\"But I'm certain this very memory is hiding the truth behind my lost memories...\"",
  ui_story_5087_50871601_21_dialog_content = "\"Why don't I remember living with my parents?\"",
  ui_story_5087_50871601_22_dialog_content = "\"Why is Nepolis confined to living within the mirror?\"",
  ui_story_5087_50871601_23_dialog_content = "\"Why am I always unhappy as if there's a bottomless abyss in my heart?\"",
  ui_story_5087_50871601_24_dialog_content = "\"The answers I seek are definitely hidden within the magic mirror that has never left my side...\"",
  ui_story_5087_50871601_25_dialog_content = "\"So, I'm heading into the mirror. Nepolis is there, and I'm finally going to her side.\"",
  ui_story_5087_50871601_26_dialog_content = "\"Thank you, PlayerName.\"",
  ui_story_5087_50871601_27_dialog_content = "That's it for my message.",
  ui_story_5087_50871601_28_dialog_content = "<color=#e8d9bb>The mirror waits ahead with a soft and gentle glow, just like the day Nikinis awoke in the frozen cave.</color>",
  ui_story_5087_50871601_29_dialog_content = "<color=#e8d9bb>Nikinis takes a deep breath and steps forward toward her mirror image...</color>",
  ui_story_5087_50871601_30_dialog_content = "(That's how I walked into the mirror world and awoke in this field of flowers...)",
  ui_story_5087_50871601_31_dialog_content = "(I strolled hand in hand with my sister and indulged in the carefree joy this place had to offer.)",
  ui_story_5087_50871601_32_dialog_content = "(If only I could immerse myself in this dream... But—)",
  ui_story_5087_50871601_33_dialog_content = "Nikinis, I've brought new lily bulbs for you. We can plant them in the empty space over there!",
  ui_story_5087_50871601_34_dialog_content = "Wow! The beauty of Nikinis' flower field never stops growing! I'll bring some seeds next time.",
  ui_story_5087_50871601_35_dialog_content = "(The flower field is so lush and beautiful from the help of numerous Northlanders.)",
  ui_story_5087_50871601_36_dialog_content = "Nikinis, I'll help plow the soil! Ho! It's really frozen solid.",
  ui_story_5087_50871601_37_dialog_content = "I'll help with the watering!",
  ui_story_5087_50871601_38_dialog_content = "(It is the water from Northland's melted snow that allows the delicate narcissuses to sprout and bloom.)",
  ui_story_5087_50871601_39_dialog_content = "This dream... It's time to wake up.",
  ui_story_5087_50871601_40_dialog_content = "Why? Have you forgotten the story's ending?",
  ui_story_5087_50871601_41_dialog_content = "The ending...",
  ui_story_5087_50871601_42_dialog_content = "\"From that day on, a lily flower blossomed out of the narcissus, and they both lived happily ever after.\"",
  ui_story_5087_50871601_43_dialog_content = "How could you think of abandoning me again after promising me an ending like that?",
  ui_story_5087_50871601_44_dialog_content = "Nikinis!",
  ui_story_5087_50871601_45_dialog_content = "No, that's not it! I—",
  ui_story_5087_50871601_46_dialog_content = "<color=#e8d9bb>Nikinis is about to defend herself when she falls silent at the sight of her \"sister.\"</color>",
  ui_story_5087_50871601_47_dialog_content = "You're not my sister... You're the mirror...",
  ui_story_5087_50871601_48_dialog_content = "Nepolis lost to you after all...",
  ui_story_5087_50871601_49_dialog_content = "Lose? Win? It's all your imagination, Nikinis.",
  ui_story_5087_50871601_50_dialog_content = "I'm your sister, and she is me. The only option you have is to believe!",
  ui_story_5087_50871601_51_dialog_content = "Otherwise, wouldn't it leave you with no choice but to fight me?",
  ui_story_5087_50871601_52_dialog_content = "I—",
  ui_story_5087_50871601_53_dialog_content = "Stopping me, crushing me, trampling upon my desires, and destroying my hope to survive... Are you really capable of all that?",
  ui_story_5087_50871601_54_dialog_content = "You can't, can you? Because you're Nikinis, the narcissus who loves the lily...",
  ui_story_5087_50871601_55_dialog_content = "No, I... You're not...",
  ui_story_5087_50871601_56_dialog_content = "Now, return to my side. Allow me to replace you and seek freedom... Urgh—",
  ui_story_5087_50871601_57_dialog_content = "Urgh... Aaaaahhh!",
  ui_story_5087_50871601_58_dialog_content = "... Nikinis...",
  ui_story_5087_50871601_59_dialog_content = "Nepolis?",
  ui_story_5087_50871601_60_dialog_content = "Nepolis, is that you? You're still here? You really are... It's not my imagination. You didn't lose to it—",
  ui_story_5087_50871601_61_dialog_content = "... The story's... ending...",
  ui_story_5087_50871601_62_dialog_content = "The ending? I see. So you do wish to live again, right?",
  ui_story_5087_50871601_63_dialog_content = "Of course, it's only right that you live and take my place in reality—",
  ui_story_5087_50871601_64_dialog_content = "No...",
  ui_story_5087_50871601_65_dialog_content = "?",
  ui_story_5087_50871601_66_dialog_content = "\"Though the lily returned, her purity was lost. She became a black flower stained black by tainted snow.\"",
  ui_story_5087_50871601_67_dialog_content = "That is... the true ending...",
  ui_story_5087_50871601_68_dialog_content = "Nepolis, what are you saying—",
  ui_story_5087_50871601_69_dialog_content = "The magic mirror and I are inseparable now, and I'm no longer who I was. It's time... for me to go.",
  ui_story_5087_50871601_70_dialog_content = "But it's different for you.",
  ui_story_5087_50871601_71_dialog_content = "I don't want to hear another word! Nepolis... Everything will be all right...",
  ui_story_5087_50871601_72_dialog_content = "Nikinis, my beloved sister, will not lay down in the dark snow.",
  ui_story_5087_50871601_73_dialog_content = "She will cross the snow and overcome the suffering brought about by fate...",
  ui_story_5087_50871601_74_dialog_content = "She will go beyond her sister's protection to see the world and love more people...",
  ui_story_5087_50871601_75_dialog_content = "She will grow dignified and strong to protect Northland's legacy, fables, and poems, and she will spread the blessing of flowers to lands afar...",
  ui_story_5087_50871601_76_dialog_content = "She will pick up what was forgotten, retake what was lost, and write an end to our poem so that a new ode may be born!",
  ui_story_5087_50871601_77_dialog_content = "So, fight.",
  ui_story_5087_50871601_78_dialog_content = "!",
  ui_story_5087_50871601_79_dialog_content = "Crush me, destroy me, and put an end to me, so that the magic mirror will have nothing left to rely on!",
  ui_story_5087_50871601_80_dialog_content = "Let me return the future you deserve, so that you may fly high with your wings—",
  ui_story_5087_50871601_81_dialog_content = "I believe in you.",
  ui_story_5087_50871601_82_dialog_content = "Nepolis...",
  ui_story_5087_50871601_83_dialog_content = "Urgh... Urgh... Aaaah!",
  ui_story_5087_50871601_84_dialog_content = "Hehe... In the end, you still stubbornly refuse to embrace the only path to happiness, huh? My sister...",
  ui_story_5087_50871601_85_dialog_content = "NEPOLIS! Aahhhh!",
  ui_story_5087_50871602_1_dialog_content = "<color=#e8d9bb>The dark green reflection of the Aurora meanders across the waters of Lake Mirror like a snake gliding beneath its surface.</color>",
  ui_story_5087_50871602_2_dialog_content = "<color=#e8d9bb>The screams and clangs of battle have faded away. Clear as a mirror, and the same as ever, eternally Lake Mirror.</color>",
  ui_story_5087_50871602_3_dialog_content = "...",
  ui_story_5087_50871602_4_dialog_content = "<color=#e8d9bb>\"I'll be there when you need me...\"</color>",
  ui_story_5087_50871602_5_dialog_content = "<color=#e8d9bb>Nepolis' last words remain lingering in Nikinis' ears.</color>",
  ui_story_5087_50871602_6_dialog_content = "<color=#e8d9bb>She stands there silently among the shredded, fluttering pure white petals.</color>",
  ui_story_5087_50871602_7_dialog_content = "<color=#e8d9bb>The intoxicating floral fragrance fills the air.</color>",
  ui_story_5087_50871602_8_dialog_content = "Nikinis! You did it!",
  ui_story_5087_50871602_9_dialog_content = "If you hadn't stopped the magic mirror in time, PlayerName and I wouldn't have made it out alive! You saved us!",
  ui_story_5087_50871602_10_dialog_content = "... That was terrifying! I don't think I'll ever be able to bear the sight of snow again...",
  ui_story_5087_50871602_11_dialog_content = "Don't say that! You're going to get tired of the sight of snow in Northland.",
  ui_story_5087_50871602_12_dialog_content = "Nikinis, I'm sorry for making you face everything on your own...",
  ui_story_5087_50871602_13_dialog_content = "I'm fine, Your Majesty. And... PlayerName—",
  ui_story_5087_50871602_14_dialog_content = "Thank you.",
  ui_story_5087_50871602_15_dialog_content = "... You don't look like you need more convincing.",
  ui_story_5087_50871602_16_dialog_content = "I'll see you on the other side!",
  ui_story_5087_50871602_17_dialog_content = "Hey! W-Wait a minute! Shaya! What are you doing... Ahhhhh! We're jumping in? I need more time to prepare myself for this—",
  ui_story_5087_50871602_18_dialog_content = "<color=#e8d9bb>Splash! Ripples surge through the lake, yet it's soon peaceful again.</color>",
  ui_story_5087_50871602_19_dialog_content = "<color=#e8d9bb>The scent of flowers wafts past Nikinis. She is once again left alone among the flowers in the field.</color>",
  ui_story_5087_50871602_20_dialog_content = "Nepolis...",
  ui_story_5087_50871602_21_dialog_content = "Time to leave for the world you fought so hard for me... the world without you.",
  ui_story_5087_50871602_22_dialog_content = "I must live well even if you're not there... Right?",
  ui_story_5087_50871602_23_dialog_content = "<color=#e8d9bb>Nikinis gradually approaches Lake Mirror. If only she could stay by the lake for a little longer, just a little longer.</color>",
  ui_story_5087_50871602_24_dialog_content = "<color=#e8d9bb>Unfortunately, it only takes her a few steps to reach the edge. Nikinis looks down as the lake water wets the hems of her dress—</color>",
  ui_story_5087_50871602_25_dialog_content = "N-Nepolis?",
  ui_story_5087_50871602_26_dialog_content = "<color=#e8d9bb>Nikinis and Nepolis' figures are reflected on the lake's surface.</color>",
  ui_story_5087_50871602_27_dialog_content = "<color=#e8d9bb>The twins dance by the lake, accompanied by flecks of pure white fluttering with the wind—a dance of drifting snow and falling petals.</color>",
  ui_story_5087_50871602_28_dialog_content = "<color=#e8d9bb>Dance! Dance eternally until the end of time!</color>",
  ui_story_5087_50871602_29_dialog_content = "<color=#e8d9bb>This would be a truly wonderful end to the story—a beautiful poem known only to the wind and snow.</color>",
  ui_story_5087_50871602_30_dialog_content = "My sister... I'll be there when you need me...",
  ui_story_5087_50871602_31_dialog_content = "<color=#e8d9bb>Splash! Ripples surge through the lake once again.</color>",
  ui_story_5087_50871602_32_dialog_content = "<color=#e8d9bb>Yet the beautiful, poetic reflection remains.</color>",
  ui_story_5087_50871602_33_dialog_content = "<color=#e8d9bb>It remains surrounded by snow, shimmering within the mirror...</color>"
}
return config
